/* harmony default export */ __webpack_exports__["default"] = ("<!-- class=\"read-only-typeahead\" -->\n<div \n    *ngIf=\"showDisplayText\"\n    class=\"read-only-typeahead\"\n    [ngClass]=\"{'small-read-only-typeahead': (typeaheadSize === 'small'), 'large-read-only-typeahead': (typeaheadSize === 'large'), 'invalid': !isValid && !disabled, 'read-only': readOnly, 'disabled': disabled && !readOnly}\"\n    (mousedown)=\"toggleDisplayText(false)\">\n  <span class=\"read-only-text\" [ngClass]=\"{'placeholder': displayText.length === 0 }\">\n    {{displayText.length > 0 ? displayText : placeholder}}\n    <span *ngIf=\"selections?.length > 0 && selections[selections.length - 1].secondaryLabel?.length > 0\" class=\"secondary-label\">{{selections[selections.length - 1].secondaryLabel}} </span>\n  </span>\n  <span *ngIf=\"!hideArrow\" class=\"down-arrow-icon\"></span>\n</div>\n<div style=\"position:relative\">\n  <a *ngIf=\"!showDisplayText && showClearIcon\" class=\"ld-link clear-selection-link\" (click)=\"clearSelectionAndFormData()\">clear</a>\n</div>\n<p-autoComplete #autocomplete\n    [ngStyle]=\"{'display': showDisplayText ? 'none' : 'block'}\" \n    (completeMethod)=\"search($event.query)\"\n    [suggestions]=\"results\"\n    [(ngModel)]=\"lastSelected\"\n    (onSelect)=\"onSuggestionSelected($event)\"\n    [field]=\"'label'\"\n    [disabled]=\"disabled\"\n    [placeholder]=\"placeholder\"\n    [styleClass]=\"typeaheadSize === 'small' ? 'ng-autocomplete-small' : 'ng-autocomplete-large'\"\n    styleClass=\"ng-autocomplete-small\"\n    [ngClass]=\"{'invalid': !isValid}\"\n    [minLength]=\"minSearchLength\" \n    (mouseup)=\"toggleDisplayText(false)\"\n    (keydown.enter)=\"onEnterKeyDown($event)\"\n    dropdownIcon=\"down-arrow-icon\"\n    [emptyMessage]=\"noResultMessage\"\n    showTransitionOptions=\"0ms ease-out\"\n    hideTransitionOptions=\"0ms ease-in\"\n    [appendTo]=\"subcontent\"\n    autocomplete=\"chrome-off\"\n    >\n    <!-- Typeahead suggestion types -->\n    <ng-template let-suggestion pTemplate=\"item\">\n      <!-- category -->\n      <div *ngIf=\"suggestion.isCategoryLabel\" class=\"ui-helper-clearfix dropdown-item category\" style=\"pointer-events: none;\" (click)=\"checkDisabledOption($event, suggestion)\">\n        <!-- Default -->\n        <span *ngIf=\"!customOptionTpl\">{{suggestion.label}}</span>\n        <!-- Custom template -->\n        <ng-container *ngTemplateOutlet=\"customOptionTpl; context: {$implicit: {suggestion: suggestion, multiSelections: multiSelections, hideErrorIcon: hideErrorIcon, hasChildren: hasChildren}}\"></ng-container>\n      </div>\n      <!-- normal and parent suggestions -->\n      <div \n          *ngIf=\"!suggestion.isCategoryLabel && !multiSelect && !(suggestion.isCustom && isDuplicate(suggestion))\" \n          class=\"ui-helper-clearfix dropdown-item\"\n          (click)=\"checkDisabledOption($event, suggestion)\"\n          [ngClass]=\"{'large-suggestion': typeaheadSize === 'large', 'small-suggestion': typeaheadSize ==='small', 'disabled-section': suggestion.disabled, 'selected-entry':suggestion.selected}\" \n          [ngStyle]=\"{'pointer-events': 'all'}\">\n        <!-- Default -->\n        <ng-container *ngIf=\"!customOptionTpl\">\n          <span [title]=\"suggestion.name || suggestion.value\" [ngClass]=\"{'italic': suggestion.disabled}\">{{suggestion.label}}</span>\n          <span *ngIf=\"suggestion.secondaryLabel?.length > 0\" class=\"secondary-label\"> {{suggestion.secondaryLabel}}</span>\n          <span *ngIf=\"suggestion.isCustom\" class=\"italic\"> (custom)</span>\n          <span *ngIf=\"hasChildren(suggestion)\" [ngStyle]=\"{'padding': !hideErrorIcon && suggestion.disabled ? '0px 2px' : ''}\"> ▸ </span>\n          <div *ngIf=\"!hideErrorIcon && suggestion.disabled\"\n            class=\"validation-error-icon validation-error-icon-xtra-small suggestion-error-icon\"\n            [pTooltip]=\"tooltipErrorMessage\"\n            tooltipPosition=\"top\">\n          </div>\n        </ng-container>\n        <!-- Custom template -->\n        <ng-container *ngTemplateOutlet=\"customOptionTpl; context: {$implicit: {suggestion: suggestion, multiSelections: multiSelections, hideErrorIcon: hideErrorIcon, hasChildren: hasChildren.bind(this)}}\"></ng-container>\n      </div>\n      <!-- multiselect suggestions -->\n      <div \n          (click)=\"selectMultiSelect($event, suggestion)\" \n          *ngIf=\"!suggestion.isCategoryLabel && multiSelect\" \n          class=\"ui-helper-clearfix dropdown-item suggestion\" \n          [ngClass]=\"{'disabled-section': suggestion.disabled }\"\n          style=\"pointer-events: auto;\">\n        <!-- Default -->\n        <ng-container *ngIf=\"!customOptionTpl\">\n          <p-checkbox\n              [(ngModel)]=\"multiSelections\"\n              value=\"{{suggestion.name}}\"\n              styleClass=\"ng-checkbox-small\"\n              readonly=\"true\">\n          </p-checkbox>\n          <span>{{suggestion.label}}</span>\n          <span *ngIf=\"suggestion.isCustom\" class=\"italic\"> (custom)</span>\n          <div *ngIf=\"!hideErrorIcon && suggestion.disabled\" class=\"validation-error-icon validation-error-icon-xtra-small\"></div>\n        </ng-container>\n        <!-- Custom template -->\n        <ng-container *ngTemplateOutlet=\"customOptionTpl; context: {$implicit: {suggestion: suggestion, multiSelections: multiSelections, hideErrorIcon: hideErrorIcon, hasChildren: hasChildren}}\"></ng-container>\n      </div>\n    </ng-template>\n</p-autoComplete>\n\n<div class=\"typeahead-subcontent\" \n    [ngStyle]=\"{'width.px': this.autocomplete.hasOwnProperty('inputEL') ? this.autocomplete.inputEL.nativeElement.offsetWidth : 0, 'position': 'absolute', 'z-index': autocomplete.overlay?.style.zIndex}\" \n    #subcontent>\n  <!-- Content that shows under the input and above the suggestions when the menu is open -->\n  <!-- Always display subcontent if a custom subcontent template is passed, let template handle hiding subcontent -->\n  <div *ngIf=\"!disableBreadcrumbs\" [ngStyle]=\"{'display': (selections && (customSubcontentTpl || nestingRoot || multiSelect || hasChildren(selections[0])) && !showDisplayText && autocomplete.overlayVisible ? 'block' : 'none')}\" class=\"typeahead-selections\"\n  (click)=\"clickOut($event)\"\n  >\n  <!-- Default -->\n    <ng-container *ngIf=\"!customSubcontentTpl\">\n      <!-- Multi Selections -->\n      <ng-container *ngIf=\"multiSelect\">\n        <ng-container *ngFor=\"let item of selections; let i = index\">\n          <span class=\"multi-selection\">{{item.label}}</span>\n          <span *ngIf=\"i !== selections.length - 1\">, </span>\n        </ng-container>\n      </ng-container>\n      <!-- Parent Selections -->\n      <ng-container *ngIf=\"!multiSelect && selections && (nestingRoot || hasChildren(selections[0]))\">\n        <span *ngIf=\"nestingRoot\" class=\"standard-selection parent-selection\" (click)=\"selectParent(-1)\">{{ customNestingRootLabel || nestingRoot }}</span>\n        <span *ngIf=\"nestingRoot\"> »  </span>\n        <ng-container *ngFor=\"let item of selections; let i = index\">\n          <span *ngIf=\"!hasChildren(item)\" class=\"standard-selection current-selection\">{{item.label}}</span>\n          <span *ngIf=\"hasChildren(item)\" class=\"standard-selection parent-selection\" (click)=\"selectParent(i)\">{{item.label}}</span>\n          <span *ngIf=\"hasChildren(item)\"> »  </span>\n        </ng-container>\n      </ng-container>\n    </ng-container>\n    <!-- Custom template -->\n    <ng-container *ngTemplateOutlet=\"customSubcontentTpl; context: {$implicit: {selections: selections, multiSelect: multiSelect, nestingRoot: nestingRoot, hasChildren: hasChildren, selectParent: selectParent}}\"></ng-container>\n  </div>\n  <!-- Custom empty message html, when simple empty message text for p-autocomplete isn't enough -->\n  <div *ngIf=\"autocomplete.overlayVisible && results && results.length === 0\" class=\"custom-empty-message-container\">\n    <div class=\"custom-empty-message-text\">\n      {{ metaDataRefreshInProgress ? 'Refreshing Data...' : noResultMessage }}\n    </div>\n    <div\n      *ngIf=\"refreshMetaData && !metaDataRefreshInProgress\"\n      class=\"refresh-icon\"\n      (click)=\"refreshMetaDataHandler($event)\"\n      pTooltip=\"Refresh Data\"\n      tooltipPosition=\"right\"\n      tooltipZIndex=\"1020\"\n    ></div>\n    <p-progressSpinner\n      *ngIf=\"refreshMetaData && metaDataRefreshInProgress\"\n      [style]=\"{width: '20px', height: '20px'}\"\n      strokeWidth=\"10\"\n      animationDuration=\"1s\"\n    ></p-progressSpinner>\n  </div>\n</div>\n");

