/* harmony default export */ __webpack_exports__["default"] = ("<div id=\"assign-contact-roles-page\" class=\"angular-page-wrapper-props ld-body-medium\">\n  <div style=\"margin-bottom: 18px\">\n    <div class=\"ld-header\">Advanced Settings</div>\n    <div class=\"ld-subheader\">Contact Roles</div>\n    <div class=\"ld-body-large\">\n      Assign a Contact Role to a matched or routed Opportunity in Contact and Opportunity graphs.\n      <br>\n      The Contact Role Rules below will be applied to the Assign a Contact Role node.\n    </div>\n  </div>\n  <div class=\"rules-table-section\">\n    <div class=\"rules-table-header\">\n      <div class=\"ld-section-header\">Contact Role Rules</div>\n      <div class=\"button-wrapper\"\n        [class.disable-cursor]=\"expanded\">\n        <div\n          class=\"ld-primary-small-button\" \n          [class.disabled]=\"expanded\"\n          type=\"button\"\n          (click)=\"handleCreateRule()\"\n        >Create Rule</div>\n      </div>\n    </div>\n    <ld-data-table\n      [options]=\"dataTableOptions\"\n      [data]=\"contactRoleRules\"\n      [addDataEmitter]=\"addDataTableEmitter\"\n      [removeRowsListener]=\"removeDataTableEmitter\"\n    >\n      <ng-template expandableRowContent let-rowData=\"rowData\" let-originalRowData=\"originalRowData\" let-rowIndex=\"rowIndex\">\n        <div class=\"main-content\">\n          <div class=\"expanded-header-row\">\n            <div class=\"ld-body-medium-bold\" [ngStyle]=\"{'margin-right': '10px', 'display': 'inline-block'}\">Contact Role</div>\n            <div class=\"contact-role-typeahead-container\">\n              <ld-typeahead\n                class=\"contact-role-typeahead-selector\"\n                placeholder=\"Find and Select Contact Role\"\n                [hideArrow]=\"true\"\n                [(selections)]=\"selection\"\n                [data]=\"contactRoles\"\n                (onSelect)=\"selectContactRole($event, rowData)\"\n                [required]=\"true\"\n                [disableBreadcrumbs]=\"true\">\n              </ld-typeahead>\n            </div>\n            <p-checkbox\n              class=\"replace-existing-checkbox\"\n              [binary]=\"true\"\n              [(ngModel)]=\"rowData.replaceExisting\"\n              styleClass=\"ng-checkbox-small\"\n              label=\"Replace Existing Contact Role (if any)\"\n              [style]=\"{ 'margin-left': '35px'}\"\n            ></p-checkbox>\n            <p-checkbox\n              [binary]=\"true\"\n              [(ngModel)]=\"rowData.markPrimary\"\n              styleClass=\"ng-checkbox-small\"\n              [style]=\"{ 'margin-left': '35px' }\"\n              label=\"Mark Primary\"\n            ></p-checkbox>\n          </div>\n          <div *ngIf=\"!rowData.roleValid\" class=\"typeahead-error-text\">\n            The role you’ve selected has been deleted or is unavailable. Please select a different role.\n          </div>\n          <div class=\"conditions-list-container\">\n            <ld-conditions-list\n              [model]=\"rowData\"\n              primarySObject=\"Contact\"\n              [usePrimarySObject]=\"true\"\n              placeholder=\"Select Contact Field\"\n              [hideFieldValueColumn]=\"true\"\n              [showDescription]=\"false\"\n              [isTrigger]=\"false\"\n              [isUpdateTrigger]=\"false\"\n              (conditionsChangeHandler)=\"handleConditionsChanged(rowData, $event)\"\n            ></ld-conditions-list>\n          </div>\n        </div>\n      </ng-template>\n\n      <ng-template footerContent let-rowData=\"rowData\" let-originalRowData=\"originalRowData\" let-rowIndex=\"rowIndex\">\n        <ng-container [ngSwitch]=\"defaultRowState\">\n          <tr *ngSwitchCase=\"'showAddDefaultRole'\" class=\"add-default-role\">\n            <td></td>\n            <td colspan=\"6\">\n              <div class=\"centered-flex\">\n                <div class=\"ld-body-medium ld-link\" \n                  [ngClass]=\"expanded ? 'disabled' : ''\"\n                  (click)=\"handleOpenDefaultTypeahead()\"\n                >Add Default Role</div>\n                <ld-tooltip\n                  [content]=\"defaultRoleTooltip\"\n                  position=\"right\"\n                  size=\"medium\"\n                ></ld-tooltip>\n              </div>\n            </td>\n          </tr>\n\n          <tr *ngSwitchCase=\"'showDefaultRole'\" class=\"show-default-role\">\n            <td><div class=\"footer-label\">Default</div></td>\n            <td colspan=\"4\">\n              <div class=\"centered-flex default-role-container\">\n                <div *ngIf=\"!defaultRoleIsValid\" class='validation-error-icon validation-error-icon-xtra-small'></div>\n                <div class=\"ld-body-medium default-contact-role\" [ngClass]=\"defaultRoleIsValid ? '' : 'invalid-role'\">{{ defaultRole }}</div>\n                <ld-tooltip\n                  [content]=\"defaultRoleTooltip\"\n                  position=\"right\"\n                  size=\"medium\"\n                ></ld-tooltip>\n              </div>\n            </td>\n            <td colspan=\"2\">\n              <div class=\"centered-flex edit-role\">\n                <div\n                  class=\"ld-action-button light-button edit-role-button\"\n                  (click)=\"handleEditRole()\"\n                >Edit</div>\n                <div class=\"ld-cross-icon-large\" (click)=\"handleDeleteDefaultRole()\"></div>\n              </div>\n            </td>\n          </tr>\n\n          <tr *ngSwitchCase=\"'showDefaultRoleTypeahead'\" class=\"show-default-typeahead\">\n            <td colspan=\"4\">\n              <div class=\"centered-flex\">\n                <div class=\"footer-label\">Default Contact Role</div>\n                <ld-typeahead\n                  class=\"contact-role-typeahead-selector\"\n                  placeholder=\"Find and Select Contact Role\"\n                  [hideArrow]=\"true\"\n                  [data]=\"contactRoles\"\n                  [(selections)]=\"defaultRoleSelection\"\n                  (onSelect)=\"selectDefaultRole($event)\"\n                  [required]=\"true\"\n                  [disableBreadcrumbs]=\"true\"\n                  >\n                </ld-typeahead>\n              </div>\n              <div *ngIf=\"!defaultRoleIsValid\" class=\"typeahead-error-text\">\n                The role you’ve selected has been deleted or is unavailable. Please select a different role.\n              </div>\n            </td>\n            <td colspan=\"3\">\n              <div class=\"centered-flex default-typeahead-controls\" [ngClass]=\"!defaultRoleIsValid ? 'button-group' : ''\">\n                <div class=\"ld-tertiary-small-button light-button\" (click)=\"handleCancelDefaultRole()\">Cancel</div>\n                <div class=\"ld-primary-small-button\"\n                  [ngClass]=\"defaultAddDisabled ? 'disabled' : ''\"\n                  (click)=\"handleAddDefaultRole()\"\n                >Done</div>\n              </div>\n            </td>\n          </tr>\n\n          <div *ngSwitchDefault></div>\n        </ng-container>\n      </ng-template>\n    </ld-data-table>\n  </div>\n</div>\n");

