/* harmony default export */ __webpack_exports__["default"] = ("<!-- Audit Logs Header -->\n<div id=\"audit-logs-table-header-wrapper\" [ngClass]=\"['ld-body-large', tableViewType]\" [style.top.px]=\"headerHeight\">\n  <div class=\"_sObjectType-header table-column-label\">{{ (objectType | sObjLabel | labelData).label || objectType | sObjLabel }}</div>\n  <div *ngIf=\"objectType\" class=\"_path-header table-column-label\">Path</div>\n  <div *ngIf=\"objectType\" class=\"_outcome-header table-column-label with-action-menu\">\n    <span>Outcome</span>\n    <p-dropdown\n      *ngIf=\"collapsible\"\n      [(ngModel)]=\"tableViewType\"\n      [options]=\"viewTypeOptions\"\n      [disabled]=\"isChangingTableViewType || isFetchingData\"\n      (onChange)=\"onChangeTableViewType()\"\n      styleClass=\"ng-action-menu\"\n      dropdownIcon=\"down-arrow-icon no-transition\">\n    </p-dropdown>\n  </div>\n</div>\n\n<!-- Audit Logs Body Wrapper -->\n<ng-container *ngIf=\"isFetchingData || isChangingTableViewType; then loadingLogs; else logsTable\"></ng-container>\n<ng-template #loadingLogs>\n  <div *ngIf=\"isFetchingData || isChangingTableViewType\" class=\"loading-logs\">\n    <ng-container *ngTemplateOutlet=\"progressSpinner\"></ng-container>\n    <div class=\"loading-text\">Loading Logs</div>\n  </div>\n</ng-template>\n<ng-template #logsTable>\n  <ng-container *ngIf=\"objectKeys(processedLogs).length === 0; then emptyTableBody; else logsTableBody\"></ng-container>\n  <ng-template #emptyTableBody>\n    <div id=\"audit-logs-table-body-wrapper\" class=\"ld-body-large empty-table\">\n      {{ tableStatusText }}\n    </div>\n  </ng-template>\n  <ng-template #logsTableBody>\n    <div *ngIf=\"currentPageResults\" id=\"audit-logs-table-body-wrapper\" [ngClass]=\"['ld-body-medium', tableViewType]\">\n      <div *ngFor=\"let log of processedLogs | keyvalue: asIsOrder; let idx = index\" class=\"table-row\">\n        <ng-container *ngIf=\"!log.value.errorLogId; then logTableRow else invalidTableRow\"></ng-container>\n        <ng-template #logTableRow>\n          <!-- Expand Button Column (Collapsed View Only) -->\n          <div *ngIf=\"tableViewType === 'collapsed'\" class=\"table-cell-wrapper\">\n            <div class=\"table-cell\">\n              <svg class=\"audit-log-accordion\" [class.collapsed]=\"!locallyExpandedLogs[currentPageResults.page]?.has(idx)\" viewBox=\"0 0 10 10\" (click)=\"onChangeLogViewType(idx)\">\n                <use href='#Accordion-Icon'></use>\n              </svg>\n            </div>\n          </div>\n          <!-- Record Column -->\n          <div class=\"table-cell-wrapper\">\n            <div class=\"table-cell\">\n              <ng-container *ngTemplateOutlet=\"recordColumn; context: { log: log, idx: idx }\"></ng-container>\n            </div>\n          </div>\n          <!-- Path Column -->\n          <div class=\"table-cell-wrapper\">\n            <div class=\"table-cell\">\n              <ng-container *ngTemplateOutlet=\"log.value.path ? pathColumn : progressSpinner; context: { log: log, idx: idx }\"></ng-container>\n            </div>\n          </div>\n          <!-- Outcome Column -->\n          <div class=\"table-cell-wrapper\">\n            <div class=\"table-cell\">\n              <ng-container *ngTemplateOutlet=\"log.value.outcome ? outcomeColumn : progressSpinner; context: { log: log, idx: idx }\"></ng-container>\n            </div>\n          </div>\n        </ng-template>\n        <ng-template #invalidTableRow>\n          <div class=\"table-cell-wrapper\">\n            <div class=\"table-cell error-message\">Error: Log with Id '{{ log.value.errorLogId }}' is Malformed</div>\n          </div>\n        </ng-template>\n      </div>\n    </div>\n  </ng-template>\n</ng-template>\n\n<!-- Record Column -->\n<ng-template #recordColumn let-log=\"log\" let-idx=\"idx\">\n  <ng-container *ngIf=\"tableViewType === 'expanded' || locallyExpandedLogs[currentPageResults.page]?.has(idx); then expandedRecordView; else collapsedRecordView\"></ng-container>\n\n  <!-- Expanded View -->\n  <ng-template #expandedRecordView>\n    <!-- Standard Keys/Values -->\n    <div *ngFor=\"let data of log.value.sobjectData.default\" class=\"record-item log-entry-row-padding\">\n      <ng-container *ngTemplateOutlet=\"recordEntry; context: { data: data }\"></ng-container>\n    </div>\n    <!-- Hidden & Extra Hidden Keys/Values -->\n    <div *ngIf=\"objectType !== 'Meeting'\" class=\"record-more-info-collapse-section\">\n      <ld-more-info\n        [moreInfo]=\"log.value.sobjectData.hidden\"\n        [idToLabelMap]=\"idToLabelMap\"\n        [addFootnote]=\"log.value.sobjectData.addFootnote\">\n      </ld-more-info>\n    </div>\n  </ng-template>\n\n  <!-- Collapsed View -->\n  <ng-template #collapsedRecordView>\n    <!-- Standard Keys/Values -->\n    <ng-container *ngFor=\"let data of log.value.sobjectData.default\">\n      <div *ngIf=\"collapsedRecordLabels.has(data.label)\" class=\"record-item log-entry-row-padding\">\n        <ng-container *ngTemplateOutlet=\"recordEntry; context: { data: data }\"></ng-container>\n      </div>\n    </ng-container>\n    <ng-container *ngFor=\"let data of log.value.sobjectData.hidden\">\n      <div *ngIf=\"collapsedRecordLabels.has(data.label)\" class=\"record-item log-entry-row-padding\">\n        <ng-container *ngTemplateOutlet=\"recordEntry; context: { data: data }\"></ng-container>\n      </div>\n    </ng-container>\n  </ng-template>\n\n  <!-- Reusable Record Entry Template -->\n  <ng-template #recordEntry let-data=\"data\">\n    <span class=\"ld-field-label-small\">{{ data.label }}: </span>\n    <ld-text-or-link [input]=\"data\" [idToLabelMap]=\"idToLabelMap\"></ld-text-or-link>\n    <!-- Copy Link Icon -->\n    <div *ngIf=\"showCopyIcon && (data.label === 'Name' || data.label === 'Case Number' || (objectType === 'Meeting' && data.label === 'First Name'))\" class=\"copy-link\">\n      <svg class=\"copy-link-icon\" viewBox=\"0 0 13 13\" (click)=\"onCopy(idx)\">\n        <use href='#Copy-Link-Icon'></use>\n      </svg>\n      <div *ngIf=\"isCopied.has(idx)\" class=\"copy-link-msg\">Link Copied</div>\n    </div>\n  </ng-template>\n</ng-template>\n\n<!-- Path Column -->\n<ng-template #pathColumn let-log=\"log\" let-idx=\"idx\">\n  <ng-container *ngIf=\"tableViewType === 'expanded' || locallyExpandedLogs[currentPageResults.page]?.has(idx); then expandedPathView; else collapsedPathView\"></ng-container>\n\n  <!-- Expanded View -->\n  <ng-template #expandedPathView>\n    <div *ngFor=\"let pathData of log.value.path\" class=\"path-item expanded-path-item\">\n      <!-- Left column with icon, grey vertical line, and arrow -->\n      <div class=\"path-icon-wrapper\">\n        <svg *ngIf=\"pathData.nodeHref\" class=\"sub-menu-svg _menu-item-icon\" viewBox=\"0 0 36 25\">\n          <use \n            class=\"_node-svg-icon\" \n            [attr.href]=\"'#'+pathData.nodeHref\" \n            [attr.x]=\"pathData.xOffset\"\n            [attr.y]=\"pathData.yOffset\"\n            [attr.transform]=\"pathData.transform\">\n          </use>\n        </svg>\n        <div *ngIf=\"!pathData.nodeHref\" [ngClass]=\"pathData.nodeIcon\"></div>\n        <div *ngIf=\"!pathData.hideNextNodeArrow\" class=\"next-node-vertical-line\"></div>\n        <div *ngIf=\"!pathData.hideNextNodeArrow\" class=\"next-node-grey-arrow-icon\"></div>\n      </div>\n      <!-- All path data -->\n      <div class=\"path-info-wrapper\">\n        <!-- Show node state, such as PENDING or ERROR -->\n        <div *ngIf=\"pathData.state\" class=\"_path-data-state\">\n          <div [ngClass]=\"[pathData.state.cardClass, '_path-data-type']\">{{ pathData.state.type.toUpperCase() }}</div>\n        </div>\n        <!-- Action Name and Node Name information -->\n        <div class=\"ld-field-label-small green-label _path-data-action-name\">{{ pathData.nodeTypeName }}: {{ pathData.actionName }}</div>\n        <ld-tooltip\n          *ngIf=\"pathData.parsedMessage['trigger-based'] && pathData.nodeTypeName.includes('Trigger')\"\n          [svgTooltip]=\"{source: '#rtr-Tooltip-Icon', viewBox: '0 0 85 10'}\"\n          [classes]=\"['svg-tooltip', 'rtr-tooltip']\"\n          [content]=\"rtrTooltip\"\n          [showOnHover]=\"true\">\n        </ld-tooltip>\n        <div class=\"ld-field-label-small log-entry-row-padding _path-data-node-name\">{{ pathData.nodeName }}</div>\n        <!-- Get Records Match node only - configuration details -->\n        <div *ngIf=\"pathData.getRecordsConfigurations\">\n          <div class=\"get-record-detail-main\">\n            <span class=\"ld-field-label-small\">Search Object: </span>\n            <span>{{ pathData.getRecordsConfigurations.searchObject }}</span>\n          </div>\n          <div class=\"get-record-details-sub\">\n            <span>Related List: </span>\n            <span>{{ pathData.getRecordsConfigurations.relatedList }}</span>\n          </div>\n          <div class=\"get-record-details-sub\">\n            <span>Lookup Field: </span>\n            <span>{{ pathData.getRecordsConfigurations.lookupField }}</span>\n          </div>\n        </div>\n        <!-- Match node only - chosen sobject -->\n        <div *ngIf=\"pathData.chosenObject\" class=\"log-entry-row-padding _path-data-chosen-object\">\n          <span class=\"ld-field-label-small _path-data-chosen-object-label\">{{ pathData.chosenObject.label }}: </span>\n          <ld-text-or-link [input]=\"pathData.chosenObject\" [idToLabelMap]=\"idToLabelMap\"></ld-text-or-link>\n        </div>\n        <!-- Match node only - L2O specific case -->\n        <div *ngIf=\"pathData.additionalObject\" class=\"log-entry-row-padding _path-data-additional-object\">\n          <span class=\"ld-field-label-small _path-data-additional-object-label\">{{ pathData.additionalObject.label }}: </span>\n          <ld-text-or-link [input]=\"pathData.additionalObject\" [idToLabelMap]=\"idToLabelMap\"></ld-text-or-link>\n        </div>\n        <!-- Match node only - other matched sobjects -->\n        <div *ngIf=\"pathData.matchedObjects\" class=\"log-entry-row-padding _path-data-matched-objects\">\n          <div *ngIf=\"pathData.matchedObjects.matches.length == 0\" class=\"_no-path-data-matched-objects\">\n            {{ pathData.matchedObjects.label }}\n          </div>\n          <div *ngIf=\"pathData.matchedObjects.matches.length > 0\" class=\"_has-path-data-matched-objects\">\n            <ld-more-info\n              [moreInfo]=\"pathData.matchedObjects.matches\"\n              [idToLabelMap]=\"idToLabelMap\"\n              [customHeader]=\"pathData.matchedObjects.label\"\n            ></ld-more-info>\n          </div>\n        </div>\n        <!-- Decision node Comparison Information only -->\n        <div class=\"decision-node-comparison-wrapper\" *ngIf=\"(pathData.leftSideVariableMetadata || pathData.primitiveVariable) && (pathData.rightSideVariableMetadata || pathData.isValueComparison || objectType === 'Meeting')\">\n          <div class=\"log-entry-row-padding\">\n            <span class=\"ld-field-label-small\">Compare</span>\n          </div>\n          <div class=\"decision-object-row log-entry-row-padding\">\n            <div class=\"ld-field-label-small\">Item 1: </div>\n            <div class=\"decision-object-labeling\">\n              <ng-container [ngTemplateOutlet]=\"pathData.primitiveVariable ? leftPrimitiveVariable : leftVariable\"></ng-container>\n              <ng-template #leftVariable>\n                <span>{{ pathData.leftSideVariableMetadata.label }}</span>\n                <div class=\"decision-object-type\">Data Type: Object-{{ pathData.leftSideVariableMetadata.sObject }}\n                  <span *ngIf=\"pathData.leftSideVariableMetadata.sObjectSubType\"> ({{ pathData.leftSideVariableMetadata.sObjectSubType }})</span>\n                </div>\n              </ng-template>\n              <ng-template #leftPrimitiveVariable>\n                <span>Primitive</span>\n                <div class=\"decision-object-type\">Data Type: Text, Number, and True/False\n                </div>\n              </ng-template>\n            </div>\n          </div>\n          <div class=\"decision-object-row log-entry-row-padding\">\n            <div class=\"ld-field-label-small\">Item 2: </div>\n            <div class=\"decision-object-labeling\">\n              <ng-container [ngTemplateOutlet]=\"pathData.rightSideVariableMetadata ? variable : pathData.isValueComparison ? value : prospect\"></ng-container>\n                <ng-template #variable>{{ pathData.rightSideVariableMetadata.label }}\n                  <div *ngIf=\"pathData.rightSideVariableMetadata.sObject\" class=\"decision-object-type\">Data Type: Object-{{ pathData.rightSideVariableMetadata.sObject }}\n                    <span *ngIf=\"pathData.rightSideVariableMetadata.sObjectSubType\"> ({{ pathData.rightSideVariableMetadata.sObjectSubType }})</span>\n                  </div>\n                </ng-template>\n                <ng-template #value>Value</ng-template>\n                <ng-template #prospect>Prospect</ng-template>\n            </div>\n          </div>\n        </div>\n        <!-- Assign Contact Role node only -->\n        <div *ngIf=\"pathData.graphNodeInfo.actionType === 'Assign Contact Role'\">\n          <div\n            *ngIf=\"pathData.hasOwnProperty('contactRole'); else noContactRole\"\n            class=\"ld-field-label-small log-entry-row-padding _path-data-contact-role-name\"\n          ><div class=\"assign-contact-role-wrapper\">Assigned Contact Role:<div class=\"contact-role-text\">{{pathData.contactRole}}</div></div>\n          </div>\n          <ng-template #noContactRole>\n            <div class=\"ld-note log-entry-row-padding contact-role-no-match\"\n            >The record did not match any Contact Role rules.<br/>No Contact Role was assigned.\n            </div>\n          </ng-template>\n        </div>\n        <!-- Use this for additional ld-more-info components with new nodes -->\n        <ng-container *ngIf=\"pathData.customMoreInfoArray\">\n          <div *ngFor=\"let customMoreInfo of pathData.customMoreInfoArray\" class=\"log-entry-row-padding\">\n            <ld-more-info\n              [moreInfo]=\"customMoreInfo.moreInfo\"\n              [idToLabelMap]=\"idToLabelMap\"\n              [customHeader]=\"customMoreInfo.header\"\n            ></ld-more-info>\n          </div>\n        </ng-container>\n\n        <!-- More Info -->\n        <ld-more-info\n          class=\"_more-info-path-data\"\n          *ngIf=\"hasMoreInfo(pathData) || isValidPartner(pathData)\"\n          [moreInfo]=\"pathData.moreInfo\"\n          [idToLabelMap]=\"idToLabelMap\"\n          nestedInfoFieldName=\"idList\"\n          [onOpen]=\"openMoreInfo.bind(this)\"\n          [onClose]=\"clearMoreInfo.bind(this)\"\n          [pathData]=\"pathData\"\n        ></ld-more-info>\n        <!-- Match Node Output Variable Info -->\n        <div *ngIf=\"pathData.outputVariableMetadata\" class=\"log-entry-row-padding match-node-set-variable\">\n          <span class=\"ld-field-label-small\">Set Variable: </span>\n          <span>{{ pathData.outputVariableMetadata.label }}</span>\n        </div>\n        <div *ngIf=\"isPartnerDisabled(pathData)\" style=\"font-style:italic;\" class=\"_path-data-slack-disabled\">\n          {{ getPartnerName(pathData) }} Notifications Disabled\n        </div>\n        <!-- Dynamic Notification Info -->\n        <div\n          *ngIf=\"pathData.dynamicRecipientsData.template || pathData.dynamicRecipientsData.message\"\n          class=\"_path-data-dynamic-recipients-data\"\n        >\n          <div\n            *ngIf=\"pathData.emailEnabled && pathData.dynamicRecipientsData.header && pathData.dynamicRecipientsData.header.length > 0\"\n            class=\"ld-field-label-small log-entry-row-padding _path-data-dynamic-recipients-data-header\"\n          >\n            {{ pathData.dynamicRecipientsData.header }}\n          </div>\n          <div class=\"log-entry-row-padding _path-data-dynamic-recipients-data-template\" *ngIf=\"pathData.dynamicRecipientsData.template\">\n            <span class=\"ld-field-label-small\">Email Template: </span>\n            <ld-text-or-link [input]=\"pathData.dynamicRecipientsData.template\" [idToLabelMap]=\"idToLabelMap\"></ld-text-or-link>\n          </div>\n          <ld-more-info\n            class=\"_path-data-dynamic-recipients-more-info\"\n            *ngIf=\"pathData.dynamicRecipientsData.recipientsList && pathData.dynamicRecipientsData.recipientsList.length > 0 && pathData.emailEnabled\" \n            [moreInfo]=\"pathData.dynamicRecipientsData.recipientsList\"\n            [idToLabelMap]=\"idToLabelMap\"\n            [customHeader]=\"pathData.dynamicRecipientsData.recipientsHeader\"\n          ></ld-more-info>\n          <div\n            *ngIf=\"!pathData.emailEnabled && pathData.dynamicRecipientsData.recipientsList\"\n            style=\"font-style:italic;\"\n            class=\"_path-data-email-disabled\"\n          >\n            Email Notifications Disabled\n          </div>\n        </div>\n        <div\n          *ngIf=\"pathData.dynamicRecipientsData.chatterRecipientsList && pathData.dynamicRecipientsData.chatterRecipientsList.length > 0\" \n          class=\"_path-data-dynamic-recipients-chatter-list\"\n        >\n          <div *ngIf=\"!pathData.chatterEnabled\" style=\"font-style:italic;\" class=\"_path-data-chatter-disabled\">\n            Chatter Notifications Disabled\n          </div>\n          <ld-more-info\n            *ngIf=\"pathData.chatterEnabled\"\n            class=\"notification-recipients-section\"\n            [moreInfo]=\"pathData.dynamicRecipientsData.chatterRecipientsList\"\n            [idToLabelMap]=\"idToLabelMap\"\n            [customHeader]=\"pathData.dynamicRecipientsData.chatterRecipientsHeader\"\n          ></ld-more-info>\n        </div>\n\n        <!-- Next Edge Name -->\n        <div [ngClass]=\"[pathData.hasOwnProperty('aborted') ? 'ld-note' : '', '_next-edge-name']\">\n          {{ (pathData.hasOwnProperty('aborted') ? '' : (pathData.isRuleName ? 'Rule Name: ' : 'Edge: ')) + util.getFormattedEdgeName(pathData.nextEdgeName) }}\n        </div>\n      </div>\n    </div>\n\n    <div *ngIf=\"!log.value.hideEOF\" class=\"path-item expanded-path-item EOF-row\">\n      <div class=\"path-icon-wrapper EOF-node-icon\"></div>\n      <div class=\"ld-field-label-small green-label EOF-text\">\n        End of Flow\n      </div>\n    </div>\n  </ng-template>\n\n  <!-- Collapsed View -->\n  <ng-template #collapsedPathView>\n    <ng-container *ngFor=\"let pathData of log.value.path\">\n      <!-- Checks if node type matches any of the trigger node types, or the 6sense enrichment node -->\n      <div *ngIf=\"pathData.nodeTypeName.includes('Trigger') || pathData.actionName === 'Enrich Company'\" class=\"path-item log-entry-row-padding\">\n        <div class=\"_path-data-action-name\"><span class=\"ld-field-label-small green-label\">{{ pathData.nodeTypeName }}:</span> {{ pathData.actionName }}</div>\n        <ld-tooltip\n          *ngIf=\"pathData.parsedMessage['trigger-based'] && pathData.nodeTypeName.includes('Trigger')\"\n          [svgTooltip]=\"{source: '#rtr-Tooltip-Icon', viewBox: '0 0 85 10'}\"\n          [classes]=\"['svg-tooltip', 'rtr-tooltip']\"\n          [content]=\"rtrTooltip\"\n          [showOnHover]=\"true\">\n        </ld-tooltip>\n      </div>\n      <!-- Checks if node type is a match node that made a successful match -->\n      <ng-container *ngIf=\"pathData.nodeTypeName === 'Match'\">\n        <div *ngIf=\"pathData.chosenObject && pathData.chosenObject.value !== 'None'\" class=\"path-item log-entry-row-padding _path-data-chosen-object\">\n          <span class=\"ld-field-label-small green-label _path-data-chosen-object-label\">{{ pathData.chosenObject.label }}: </span>\n          <ld-text-or-link [input]=\"pathData.chosenObject\" [idToLabelMap]=\"idToLabelMap\"></ld-text-or-link>\n        </div>\n      </ng-container>\n      <!-- Checks if node type is an action node -->\n      <ng-container *ngIf=\"pathData.nodeTypeName === 'Action'\">\n        <div *ngIf=\"nonMatchRoutingActionTypes.has(pathData.graphNodeInfo.actionType)\" class=\"path-item log-entry-row-padding\">\n          <ng-container *ngTemplateOutlet=\"pathData.mainResult ? collapsedPathActionMainResult : collapsedPathDefault; context: { pathData: pathData }\"></ng-container>\n        </div>\n        <div *ngIf=\"createConvertActionTypes.has(pathData.graphNodeInfo.actionType) && pathData.mainResult\" class=\"path-item log-entry-row-padding\">\n          <ng-container *ngTemplateOutlet=\"collapsedPathActionMainResult; context: { pathData: pathData }\"></ng-container>\n        </div>\n      </ng-container>\n    </ng-container>\n\n    <!-- Action Node Main Result Template -->\n    <ng-template #collapsedPathActionMainResult let-pathData=\"pathData\">\n      <span class=\"ld-field-label-small green-label\">{{ pathData.mainResult.label }}: </span>\n      <ld-text-or-link [input]=\"pathData.mainResult\" [idToLabelMap]=\"idToLabelMap\"></ld-text-or-link>\n    </ng-template>\n\n    <!-- Action Node Default Collapsed Display Template -->\n    <ng-template #collapsedPathDefault let-pathData=\"pathData\">\n      <div class=\"_path-data-action-name\">\n        <span class=\"ld-field-label-small green-label\">{{ pathData.nodeTypeName }}: </span>\n        {{ pathData.actionName }}\n      </div>\n    </ng-template>\n  </ng-template>\n</ng-template>\n\n<!-- Outcome Column -->\n<ng-template #outcomeColumn let-log=\"log\" let-idx=\"idx\">\n  <ng-container *ngIf=\"tableViewType === 'expanded' || locallyExpandedLogs[currentPageResults.page]?.has(idx); then expandedOutcomeView; else collapsedOutcomeView\"></ng-container>\n\n  <!-- Expanded View -->\n  <ng-template #expandedOutcomeView>\n    <!-- PENDING or ERROR STATE additional detail section -->\n    <div *ngIf=\"log.value.outcome.nodeStates && log.value.outcome.nodeStates.length > 0\" class=\"outcome-item log-entry-section-padding\">\n      <div *ngFor=\"let state of log.value.outcome.nodeStates\" [ngClass]=\"state.textClass\">\n        <div [ngClass]=\"state.textClass\" class=\"ld-field-label-small\">{{ state.header }}</div>\n        <div [ngClass]=\"state.textClass\" class=\"ld-field-label-small\">{{ state.subheader }}</div>\n        <ld-more-info\n          class=\"_state-more-info\"\n          *ngIf=\"state.moreInfo && state.moreInfo.length > 0\"\n          [moreInfo]=\"state.moreInfo\"\n          [idToLabelMap]=\"idToLabelMap\"\n          customHeader=\"More Info ({{ state.moreInfo.length }})\"\n        ></ld-more-info>\n      </div>\n      <hr class=\"horizontal-line-separator dashed\">\n    </div>\n    <!-- Log Level Error Message Section -->\n    <ng-container *ngIf=\"log.value.outcome.logLevelErrorInfo.value.length !== 0\" class=\"_triggering-action-info\">\n      <div class=\"outcome-item log-entry-section-padding\">\n        <div *ngFor=\"let value of log.value.outcome.logLevelErrorInfo.value\" class=\"log-entry-row-padding error-message\" > {{ value }}\n        </div>\n      </div>\n    </ng-container>\n    <!-- Triggering action text - triggeringActionInfo -->\n    <ng-container *ngIf=\"log.value.outcome.triggeringActionInfo.value !== 'tagging preview'; else taggingOutcome\" class=\"_triggering-action-info\">\n      <div class=\"outcome-item log-entry-section-padding\">\n        <div class=\"ld-field-label-small log-entry-row-padding _triggering-action-info-label\">{{ log.value.outcome.triggeringActionInfo.label }}</div>\n        <div class=\"log-entry-subcontent-padding _triggering-action-info-value\">{{ log.value.outcome.triggeringActionInfo.value }}</div>\n      </div>\n      <!-- Action Outcomes -->\n      <div class=\"outcome-item log-entry-section-padding\">\n        <div class=\"ld-field-label-small log-entry-row-padding\">Action Outcomes</div>\n        <div *ngFor=\"let routingAction of log.value.outcome.actionsTakenInfo.routingActions\" class=\"log-entry-subcontent-padding\">\n          <ng-container *ngTemplateOutlet=\"routingAction.headerErrorText ? expandedOutcomeActionError : outcomeAction; context: { routingAction: routingAction }\"></ng-container>\n          <ng-template #expandedOutcomeActionError let-routingAction=\"routingAction\">\n            <span [ngClass]=\"routingAction.headerErrorClass\" class=\"_routing-action-header\">\n              - Failed: <span [innerHTML]=\"routingAction.actionHeader\"></span>&nbsp;<span [innerHTML]=routingAction.headerErrorText></span>\n            </span>\n          </ng-template>\n          <div *ngFor=\"let outcomeDetail of routingAction.outcomeDetails\" [ngClass]=\"outcomeDetail.labelTextClass\" class=\"_routing-action-outcome-detail\">\n            - <span>{{ outcomeDetail.label }}</span>\n          </div>\n        </div>\n      </div>\n      <!-- Final Owner -->\n      <div *ngIf=\"objectType !== 'Meeting'\" class=\"outcome-item log-entry-section-padding\">\n        <div\n          *ngIf=\"log.value.outcome.finalOwnerInfo && log.value.outcome.finalOwnerInfo.length > 0\"\n          class=\"ld-field-label-small log-entry-row-padding _ownership-section\"\n        >\n          Ownership\n        </div>\n        <div *ngFor=\"let finalOwner of log.value.outcome.finalOwnerInfo\" class=\"log-entry-row-padding _final-owner-label\">\n          <span>{{ finalOwner.label }}: </span>\n          <ld-text-or-link [input]=\"finalOwner\" [idToLabelMap]=\"idToLabelMap\"></ld-text-or-link>\n        </div>\n        <!-- Ownership Change History -->\n        <ld-more-info\n          class=\"_ownership-change-history-more-info\"\n          *ngIf=\"log.value.outcome.ownershipOutcomeInfo && log.value.outcome.ownershipOutcomeInfo.length > 0\"\n          [moreInfo]=\"log.value.outcome.ownershipOutcomeInfo\"\n          infoHeadersFieldName=\"nodeName\"\n          [idToLabelMap]=\"idToLabelMap\"\n        ></ld-more-info>\n      </div>\n      <!-- Booking - used for Calendaring -->\n      <div *ngIf=\"log.value.outcome.bookingInfo && log.value.outcome.bookingInfo.length > 0\" class=\"outcome-item log-entry-section-padding\">\n        <div class=\"ld-field-label-small log-entry-row-padding _booking-section\">\n          Booking\n        </div>\n        <div *ngFor=\"let booking of log.value.outcome.bookingInfo\" class=\"log-entry-row-padding _booking-label\">\n          <span>{{ booking.label }}: </span>\n          <ld-text-or-link [input]=\"booking\" [idToLabelMap]=\"idToLabelMap\"></ld-text-or-link>\n          <ld-more-info\n            *ngIf=\"booking.label == 'Scheduled' && log.value.outcome.bookingAdditionalUsers.length > 0\"\n            [customHeader]=\"log.value.outcome.bookingAdditionalUsersHeader\"\n            [moreInfo]=\"log.value.outcome.bookingAdditionalUsers\"\n            [idToLabelMap]=\"idToLabelMap\"\n          ></ld-more-info>\n        </div>\n        <div class=\"linked-info\">\n          <div class=\"linked-info-row\">\n            <span> {{ log.value.outcome.linkedLogInfo['linked record'].label }}: </span>\n            <ld-text-or-link [input]=\"log.value.outcome.linkedLogInfo['linked record']\" [idToLabelMap]=\"idToLabelMap\"></ld-text-or-link>\n          </div>\n          <div *ngIf=\"log.value.outcome.linkedLogInfo['linked contact logs']\" class=\"linked-info-row\">\n            <ld-more-info\n              customHeader=\"Contact Log(s)\"\n              [moreInfo]=\"log.value.outcome.linkedLogInfo['linked contact logs']\"\n              [idToLabelMap]=\"idToLabelMap\"\n            ></ld-more-info>\n          </div>\n          <div *ngIf=\"log.value.outcome.linkedLogInfo['linked lead logs']\" class=\"linked-info-row\">\n            <ld-more-info\n              customHeader=\"Lead Log(s)\"\n              [moreInfo]=\"log.value.outcome.linkedLogInfo['linked lead logs']\"\n              [idToLabelMap]=\"idToLabelMap\"\n            ></ld-more-info>\n          </div>\n        </div>\n      </div>\n      <div *ngIf=\"log.value.outcome.linkedCalendaringLogInfo\" class=\"linked-calendaring-log\">\n        <ld-more-info\n          customHeader=\"Meeting Log(s)\"\n          [moreInfo]=\"log.value.outcome.linkedCalendaringLogInfo\"\n          [idToLabelMap]=\"idToLabelMap\"\n        ></ld-more-info>\n      </div>\n      <!-- Additional action details - additionalActionDetails -->\n      <div\n        *ngIf=\"objectType !== 'Meeting' && log.value.outcome.additionalActionDetails && log.value.outcome.additionalActionDetails.length > 0\"\n        class=\"outcome-item log-entry-section-padding _additional-action-details-section\"\n      >\n        <hr class=\"horizontal-line-separator dashed\">\n        <div *ngFor=\"let actionDetail of log.value.outcome.additionalActionDetails\" class=\"log-entry-row-padding _additional-action-detail\">\n          <div class=\"log-entry-row-padding\">\n            <span *ngIf=\"actionDetail.label\" class=\"ld-field-label-small _additional-action-details-label\">{{ actionDetail.label }}: </span>\n            <ld-text-or-link [input]=\"actionDetail\" [idToLabelMap]=\"idToLabelMap\"></ld-text-or-link>\n          </div>\n          <!-- More info for each additional action detail -->\n          <ld-more-info\n            class=\"_additional-action-detail-more-info\"\n            *ngIf=\"actionDetail.moreInfo && actionDetail.moreInfo.length > 0\"\n            [moreInfo]=\"actionDetail.moreInfo\"\n            [idToLabelMap]=\"idToLabelMap\"\n          ></ld-more-info>\n        </div>\n      </div>\n    </ng-container>\n    <!-- Tagging preview outcome -->\n    <ng-template #taggingOutcome>\n      <ng-container *ngIf=\"log.value.outcome.matchedAccount; else noMatchesFound\" class=\"_tagging-outcome-section\">\n        <div class=\"outcome-item log-entry-section-padding\">\n          <div class=\"ld-field-label-small log-entry-row-padding _matched-account-name\">MATCHED ACCOUNT - {{log.value.outcome.matchedAccount.name}} </div>\n          <ng-container *ngFor=\"let data of log.value.outcome.matchedAccount | keyvalue\">\n            <div class=\"log-entry-row-padding _matched-account-key-value\">\n              <span class=\"ld-field-label-small\">{{ data.key }}: </span>\n              <span> {{ data.value }} </span>\n            </div>\n          </ng-container>\n        </div>\n      </ng-container>\n      <ng-template #noMatchesFound>\n        <div class=\"outcome-item log-entry-section-padding ld-field-label-small _no-matches-found\">No matches found.</div>\n      </ng-template>\n    </ng-template>\n  </ng-template>\n\n  <!-- Collapsed View -->\n  <ng-template #collapsedOutcomeView>\n    <!-- PENDING or ERROR STATE section -->\n    <div *ngIf=\"log.value.outcome.nodeStates && log.value.outcome.nodeStates.length > 0\" class=\"outcome-item log-entry-section-padding\">\n      <div *ngFor=\"let state of log.value.outcome.nodeStates\" [ngClass]=\"state.textClass\">\n        <span [ngClass]=\"['ld-link', state.textClass]\" (click)=\"onChangeLogViewType(idx)\">\n          {{ state.textClass === 'error-message' ? 'Error' : 'Pending' }}: {{ state.header }}\n        </span>\n      </div>\n      <hr class=\"horizontal-line-separator dashed\">\n    </div>\n    <!-- Log Level Error Message Section (for log-level only error messages) -->\n    <div *ngIf=\"log.value.outcome.logLevelErrorInfo.value.length !== 0\" class=\"_triggering-action-info outcome-item log-entry-section-padding\">\n      <ng-container *ngFor=\"let value of log.value.outcome.logLevelErrorInfo.value\">\n        <div *ngIf=\"value.charAt(0) !== '*'\" class=\"log-entry-row-padding error-message truncated-message ld-link\" (click)=\"onChangeLogViewType(idx)\" [innerHTML]=\"value\">\n        </div>\n      </ng-container>\n    </div>\n    <!-- Action Outcomes -->\n    <div class=\"outcome-item log-entry-section-padding\">\n      <div class=\"ld-field-label-small log-entry-row-padding\">Action Outcomes</div>\n      <div *ngFor=\"let routingAction of log.value.outcome.actionsTakenInfo.routingActions\" class=\"log-entry-subcontent-padding\">\n        <ng-container *ngTemplateOutlet=\"routingAction.headerErrorText ? collapsedOutcomeActionError : outcomeAction; context: { routingAction: routingAction }\"></ng-container>\n        <ng-template #collapsedOutcomeActionError let-routingAction=\"routingAction\">\n          <span [ngClass]=\"routingAction.headerErrorClass\" class=\"_routing-action-header\">\n            - <span class=\"ld-link\" (click)=\"onChangeLogViewType(idx)\">Failed: <span [innerHTML]=\"routingAction.actionHeader\"></span></span>\n          </span>\n        </ng-template>\n      </div>\n    </div>\n    <!-- Final Owner -->\n    <div *ngIf=\"objectType !== 'Meeting'\" class=\"outcome-item log-entry-section-padding\">\n      <div *ngIf=\"log.value.outcome.finalOwnerInfo && log.value.outcome.finalOwnerInfo.length > 0\" class=\"_ownership-section\">\n        <div>\n          <ng-container *ngTemplateOutlet=\"log.value.outcome.finalOwnerInfo[0].label.startsWith('Owner') ? outcomeSameOwner : outcomeNewOwner; context: { outcome: log.value.outcome }\"></ng-container>\n        </div>\n        <ng-template #outcomeSameOwner let-outcome=\"outcome\">\n          <span class=\"ld-field-label-small\">Same Owner (Routed {{objectTypeLabel || objectType}}): </span>\n          <ld-text-or-link [input]=\"outcome.finalOwnerInfo[0]\" [idToLabelMap]=\"idToLabelMap\"></ld-text-or-link>\n        </ng-template>\n        <ng-template #outcomeNewOwner let-outcome=\"outcome\">\n          <span class=\"ld-field-label-small\">New Owner (Routed {{objectTypeLabel || objectType}}): </span>\n          <ld-text-or-link [input]=\"outcome.finalOwnerInfo[0]\" [idToLabelMap]=\"idToLabelMap\"></ld-text-or-link>\n        </ng-template>\n        <!-- Alternate Assignment Fields -->\n        <ng-container *ngIf=\"log.value.outcome.ownershipOutcomeInfo.length > 0\">\n          <ng-container *ngTemplateOutlet=\"alternateAssignmentList; context: { alternateAssignments: getAlternateAssignments(log.value.outcome.ownershipOutcomeInfo) }\"></ng-container>\n          <ng-template #alternateAssignmentList let-alternateAssignments=\"alternateAssignments\">\n            <div *ngIf=\"alternateAssignments.length > 0\" [style.padding-top]=\"'4px'\">\n              <div *ngFor=\"let altAssign of alternateAssignments | slice:0:2\" class=\"log-entry-subcontent-padding\">\n                - <span class=\"log-entry-row-padding\">{{ altAssign.nodeDetails[0].label }}: </span>\n                <ld-text-or-link [input]=\"altAssign.nodeDetails[0]\" [idToLabelMap]=\"idToLabelMap\"></ld-text-or-link>\n              </div>\n              <div *ngIf=\"alternateAssignments.length > 2\" class=\"log-entry-subcontent-padding\">\n                - <span class=\"log-entry-row-padding\">...</span>\n              </div>\n            </div>\n          </ng-template>\n        </ng-container>\n      </div>\n    </div>\n    <!-- Booking - used for Calendaring -->\n    <div *ngIf=\"log.value.outcome.bookingInfo && log.value.outcome.bookingInfo.length > 0\" class=\"outcome-item log-entry-section-padding\">\n      <div class=\"ld-field-label-small log-entry-row-padding _booking-section\">\n        Booking\n      </div>\n      <div *ngFor=\"let booking of log.value.outcome.bookingInfo\" class=\"log-entry-row-padding _booking-label\">\n        <span>{{ booking.label }}: </span>\n        <ld-text-or-link [input]=\"booking\" [idToLabelMap]=\"idToLabelMap\"></ld-text-or-link>\n      </div>\n      <div class=\"linked-info\">\n        <div class=\"linked-info-row\">\n          <span> {{ log.value.outcome.linkedLogInfo['linked record'].label }}: </span>\n          <ld-text-or-link [input]=\"log.value.outcome.linkedLogInfo['linked record']\" [idToLabelMap]=\"idToLabelMap\"></ld-text-or-link>\n        </div>\n      </div>\n    </div>\n  </ng-template>\n\n  <!-- Reusable Action Outcome Entry Template -->\n  <ng-template #outcomeAction let-routingAction=\"routingAction\">\n    - <span [ngClass]=\"routingAction.headerTextClass\" class=\"_routing-action-header\" [innerHTML]=\"routingAction.actionHeader\"></span>\n  </ng-template>\n</ng-template>\n\n<!-- Reusable loading spinner -->\n<ng-template #progressSpinner>\n  <p-progressSpinner\n    [style]=\"{width: '100%', height: '40px'}\"\n    strokeWidth=\"4\" \n    animationDuration=\"1.5s\">\n  </p-progressSpinner>\n</ng-template>\n");

