/* harmony default export */ __webpack_exports__["default"] = ("<div id=\"meeting-metrics-wrapper\" class=\"angular-page-wrapper-props ld-body-medium\">\n  <div class=\"meeting-metrics-header\">\n    <div class=\"ld-header\"> BookIt </div>\n    <div class=\"ld-subheader\"> Metrics Dashboard </div>\n    <div class=\"meeting-metrics-subheader\">\n      <div class=\"subheader-wrapper\" style=\"width: 500px\">\n        <!-- TODO:BMD waiting on this link from the product.  -->\n        <div class=\"ld-header-description\">\n          View key BookIt metrics across a specified time frame. Please refer to the <a href=\"https://leandatahelp.zendesk.com/hc/en-us/articles/13259418097307\" target=\"_blank\">LeanData Reporting Guide</a> to create Salesforce reports for BookIt metrics.\n        </div>\n      </div>\n      <div class=\"date-range-dropdown-wrapper\">\n        <div class=\"meeting-metrics-date-range\">\n          <p-dropdown   \n            [(ngModel)]=\"selectedDate\"            \n            [options]=\"dateOptions\"\n            (onChange)=\"handleDateFilterTypeChange()\"\n            styleClass=\"ng-dropdown-small\"\n            dropdownIcon=\"down-arrow-icon no-transition\"\n          ></p-dropdown>\n        </div>\n        <div class=\"meeting-metrics-start-date\">\n          <p-calendar\n            [(ngModel)]=\"calendarStartDate\"\n            [inputStyle]=\"{'width': '83px', 'height': '27px', 'text-align-last': 'left', 'border-radius': '0px'}\"\n            styleClass=\"icon-no-button\"\n            [maxDate]=\"calendarEndDate || maxDate\"\n            readonlyInput=\"true\"\n            (onClearClick)=\"clearStartDate()\"\n            [placeholder]=\"calendarStartDate || 'mm/dd/yyyy'\"\n            (onSelect)=\"handleCustomDateChange('start')\"\n            [disabled]=\"selectedDate !== 'Custom'\"\n            showButtonBar=\"true\"\n            dateFormat=\"mm/dd/yy\"\n            [showIcon]=\"true\"\n            icon=\"calendar-icon\">\n          </p-calendar>\n        </div>\n        <div class=\"bookit-dashboard-right-arrow-icon\" style=\"margin-right: 5px;\"> </div>\n        <div class=\"meeting-metrics-end-date\">\n          <p-calendar\n            [(ngModel)]=\"calendarEndDate\"\n            [inputStyle]=\"{'width': '83px', 'height': '27px', 'text-align-last': 'left', 'border-radius': '0px'}\"\n            styleClass=\"icon-no-button\"\n            [minDate]=\"calendarStartDate\"\n            [maxDate]=\"maxDate\"\n            readonlyInput=\"true\"\n            (onClearClick)=\"clearEndDate()\"\n            [placeholder]=\"calendarEndDate || 'mm/dd/yyyy'\"\n            (onSelect)=\"handleCustomDateChange('end')\"\n            [disabled]=\"selectedDate !== 'Custom'\"\n            showButtonBar=\"true\"\n            dateFormat=\"mm/dd/yy\"\n            [showIcon]=\"true\"\n            icon=\"calendar-icon\">\n          </p-calendar>\n        </div>\n\n        <div class=\"meeting-metrics-download-csv\">\n          <div class=\"ld-secondary-small-button download-csv-btn\" style=\"float: right;\" (click)=\"handleDownloadDashboard()\"> Download CSV </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <hr class=\"horizontal-line-separator\">\n  <div class=\"meeting-metrics-dashboard\">\n    <div class=\"metrics-detail-wrapper\">\n      <div class=\"meeting-metrics-detail\">\n        <div \n          *ngIf=\"statsCardDisplayOptions.showForms\"\n          [style.width.px]=\"(statsCardDisplayOptions.showForms && statsCardDisplayOptions.showHandoff) ? '380' : '580'\"\n          style=\"background-color: #E9F0F5;\"\n          class=\"meeting-card-wrapper\">\n          <div class=\"ld-body-medium-bold\" style=\"margin-bottom: 7px;\"> BookIt for Forms (BFF) </div>\n          <div style=\"display: flex;\">\n            <div \n              [style.paddingRight.px]=\"(!statsCardDisplayOptions.showHandoff) ? '100' : '20'\"\n              class=\"meeting-scheduled-wrapper\">\n              <div class=\"meeting-metrics-number\"> {{ formsInfo.meetingsScheduled }} </div>\n              <div class=\"ld-body-large-bold\" style=\"white-space: nowrap;\"> Meetings Scheduled </div>\n            </div>\n            <div class=\"change-rate-wrapper\">\n              <div style=\"display: flex; flex-direction: row;\">\n                <div class=\"meeting-metrics-number\">\n                  {{ conversionRateInfo.conversionRate }}%\n                </div>\n                <div *ngIf=\"conversionRateInfo.conversionChangeRate\" class=\"change-rate-more-info\">\n                  <div \n                    class=\"bookit-dashboard-profit-loss-icon\"\n                    [style.margin-left.px]=\"(absoluteChangeRate() && conversionRateInfo.conversionRate === 100) ? 5 : 15\"\n                    [class.bookit-dashboard-upwards-arrow-icon]=\"conversionRateInfo.conversionChangeRate > 0\"\n                    [class.bookit-dashboard-downwards-arrow-icon]=\"conversionRateInfo.conversionChangeRate < 0\">\n                  </div>\n                  <div class=\"change-rate-number\"> {{ absoluteChangeRate() }}% </div>\n                </div>\n              </div>\n              <div style=\"display: flex; flex-direction: column;\">\n                <div class=\"ld-body-large-bold\"> Conversion Rate\n                  <ld-tooltip\n                  #tooltipRef\n                  [content]=\"conversionRateInfo.conversionRateTooltipContent\"\n                  size=\"small\"\n                  tooltipZIndex=\"1001\"\n                  position=\"right\"></ld-tooltip>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <div \n          *ngIf=\"statsCardDisplayOptions.showHandoff\"\n          [style.width.px]=\"(statsCardDisplayOptions.showForms && statsCardDisplayOptions.showHandoff) ? '190' : '580'\"\n          style=\"background-color: #EAE2EF;\" \n          class=\"meeting-card-wrapper\">\n          <div class=\"ld-body-medium-bold\" style=\"margin-bottom: 7px;\"> BookIt Handoff (BH) </div>\n          <div class=\"meeting-metrics-number\"> {{ handoffInfo.meetingsScheduled }} </div>\n          <div class=\"ld-body-large-bold\"> Meetings Scheduled </div>\n        </div>\n      </div>\n\n      <div *ngIf=\"statsCardDisplayOptions.showFunnelChart\" class=\"conversion-rate-wrapper\" style=\"background-color: #E9F0F5;\">\n        <div class=\"conversion-rate-header-content\">\n          <div class=\"conversion-rate-header\">\n            <div class=\"ld-body-medium-bold\"> BookIt for Forms (BFF) </div>\n            <div class=\"ld-body-large-bold\"> Conversion Funnel </div>\n          </div>\n          <div class=\"trigger-node-dropdown\">\n            <div class=\"ld-body-medium-bold\" style=\"margin-right: 10px;\"> Trigger Node </div>\n            <p-dropdown\n              [options]=\"triggerNodeDropdownOptions\"\n              (onChange)=\"refreshFunnelChartData()\"\n              styleClass=\"ng-dropdown-small\"\n              dropdownIcon=\"down-arrow-icon no-transition\"\n              [ngStyle]=\"{'width': '200px'}\"\n              [(ngModel)]=\"funnelChartSelection\"\n            ></p-dropdown>\n          </div>\n        </div>\n        <div class=\"conversion-rate-detail-content\">\n          <ld-funnel-chart\n            containerId=\"bookit-dashboard-funnel-chart\"\n            [data]=\"funnelChartData\"\n          ></ld-funnel-chart>\n        </div>\n      </div>\n\n      <div *ngIf=\"!statsCardDisplayOptions.showFunnelChart\" class=\"conversion-rate-wrapper\">\n        <div class=\"conversion-rate-header-content\" style=\"padding-bottom: 0px;\">\n          <div class=\"conversion-rate-header\" style=\"flex-direction: row; padding: 4px 0px;\">\n            <div class=\"ld-body-large-bold\"> BookIt for Forms </div>\n            <ld-message-badge \n              style=\"padding: 5px;\"\n              class=\"dashboard-badge\"\n              [data]=\"{\n                badgeText: 'UPGRADE',\n                header: 'Want prospects to book meetings right after webform submission?',\n                message: 'Learn more about LeanData BookIt - our Automated Scheduling solution! Please reach out to your LeanData Customer Success Team for more information.',\n                type: 'dashboard',\n                size: 'large'\n              }\"\n            ></ld-message-badge>  \n          </div>\n        </div>\n        <hr class=\"horizontal-line-separator\">\n        <div class=\"conversion-rate-detail-content\">\n          <div class=\"bookit-upgrade\" style=\"width: 470px; height: 320px; margin-left: 30px\"></div>\n          <div style=\"padding: 0px 50px;\">\n            <b>LeanData BookIt for Forms:</b> Instantly schedule meetings with prospects! Book more meetings with the speed and precision needed to transform buyer signals into buying decisions. Please reach out to your CSM for more information.\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"meeting-distribution-wrapper\" >\n      <div *ngIf=\"!searchFilterModalVisible\" style=\"position: relative; height: 580px;\">\n        <div class=\"meeting-distribution-header-content\">\n          <div class=\"meeting-distribution-header\">\n            <div class=\"ld-body-large-bold\"> Meeting Distribution\n                <ld-tooltip\n                  #tooltipRef\n                  [content]=\"meetingDistributionTooltipContent\"\n                  size=\"small\"\n                  position=\"right\">\n                </ld-tooltip>\n            </div>\n            <div class=\"ld-body-medium meeting-distribution-subheader\"> \n              <span class=\"meeting-distribution-pool-rep-list\"> {{ meetingDistributionPoolRepList }} </span>\n              <span> | </span>\n              <span class=\"meeting-distribution-clear-filter\">\n                <a\n                  class=\"ld-link\"\n                  [class.disabled]=\"!meetingDistributionFilter.current.userFilter && !meetingDistributionFilter.current.poolFilter\"\n                  (click)=\"clearSearchAndFilterModel()\"> Clear Filter </a>\n              </span>\n            </div>\n          </div>\n          <div \n            *ngIf=\"statsCardDisplayOptions.showForms && statsCardDisplayOptions.showHandoff && statsCardDisplayOptions.showFunnelChart\"\n            class=\"meeting-distribution-dropdown-wrapper\">\n            <div class=\"ld-body-medium-bold\" style=\"margin-right: 10px;\"> Product </div>\n            <p-dropdown\n              [(ngModel)]=\"selectedMeetingDistributionFilter\"\n              [options]=\"filterDropdownOptions\"\n              (onChange)=\"meetingDistributionDropdownHandler($event)\"\n              styleClass=\"ng-dropdown-small\"\n              dropdownIcon=\"down-arrow-icon no-transition\"\n              [ngStyle]=\"{'width': '90px'}\"\n            ></p-dropdown>\n          </div>\n        </div>\n        <hr class=\"horizontal-line-separator\">\n        <div class=\"meeting-distribution-detail-content\">\n          <ld-stacked-bar-chart\n            containerId=\"bookit-dashboard-stacked-bar-chart\"\n            [data]=\"barChartData\"\n            [categories]=\"barChartCategories\"\n            [inactiveValues]=\"inactiveMembers\"\n          ></ld-stacked-bar-chart>\n        </div>\n        <div class=\"search-filter-wrapper\">\n          <div \n            type=\"button\" \n            (click)=\"initSearchAndFilterModel()\"\n            class=\"bookit-dashboard-search-filter-icon\"\n            style=\"height: 70px; width: 70px;\">\n          </div>\n        </div>\n      </div>\n\n      <div *ngIf=\"searchFilterModalVisible\" id=\"search-filter-modal\">\n        <div>\n          <div style=\"display: flex; justify-content: space-between; margin-bottom: 10px;\">\n            <div class=\"ld-body-large-bold\"> Search & Filter </div>\n            <div> \n              <a (click)=\"cancelSearchAndFilterModel()\"> Cancel </a> \n              <span> | </span>\n              <!-- By User = 0, By BookIt Pool = 1 -->\n              <a\n                class=\"ld-link\"\n                [class.disabled]=\"(!meetingDistributionFilter.current.userFilter && filterTabSelectionIndex === 0) || this.bookitPoolData.length === 0\"\n                (click)=\"applySearchAndFilterModel()\">\n                Apply \n              </a>\n            </div>\n          </div>\n          <div>\n            <p-tabView [activeIndex]=\"filterTabSelectionIndex\" (onChange)=\"handleTabChange($event.index)\">\n              <p-tabPanel header=\"By User\">\n                <div>\n                  <ld-data-table\n                    [data]=\"bookitUserData\"\n                    [options]=\"userNameTableOptions\"\n                    class=\"_by-user-table bookit-user-table\">\n                  </ld-data-table>\n                </div>\n              </p-tabPanel>\n              <p-tabPanel header=\"By BookIt Pool\">\n                <div>\n                  <ld-data-table\n                    [data]=\"bookitPoolData\"\n                    [options]=\"bookitPoolTableOptions\"\n                    class=\"_by-pool-table bookit-pool-table\">\n                  </ld-data-table>\n                </div>\n              </p-tabPanel>\n            </p-tabView>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>");

