/* harmony default export */ __webpack_exports__["default"] = ("<div class=\"graph-info-wrapper\">\n  <div class=\"displayed-text\">\n    <div style=\"margin-bottom:10px\" class=\"_{{ objectType | lowercase }}-overview-text-one\">\n      Add conditions and enable up to 10 Business Units for Business Unit Tagging and Routing. LeanData will tag {{ objectType | pluralize }} that meet the conditions with the Business Unit and route them through the BU's graph. Once tagged, the record will remain in the Business Unit tagged.\n    </div>\n    <div style=\"margin-bottom:10px\" class=\"_{{ objectType | lowercase }}-overview-text-two\">\n      {{ objectType | pluralize }} not meeting the conditions will not be tagged or routed.  To track these {{ objectType | pluralize }}, create a Default Business Unit.\n      <ld-tooltip [content]=\"descriptionToolTip\" class=\"_default-business-unit-tooltip\"></ld-tooltip>\n    </div>\n  </div>\n  <div class=\"bu-deployment-wrapper\">\n    <div class=\"ld-body-small-bold _deployed-by-user\">{{ 'Deployed By ' + (deployedGraph?.CreatedBy || 'N/A') }}</div>\n    <div class=\"ld-body-medium _deployed-date\"> {{ deployedDate }} </div>\n  </div>\n</div>\n\n<div class=\"ld-section-header\" style=\"margin-bottom: 10px\">\n  Business Unit Conditions\n  <ld-tooltip \n    [content]=\"businessUnitTooltipContent\"\n    position=\"right\"\n    class=\"_evalute-business-unit-conditions-tooltip\">\n  </ld-tooltip>\n</div>\n<p-tabView class=\"_tab-view-container\">\n  <p-tabPanel header=\"Draft\" class=\"_draft-tab\">\n    <ng-template pTemplate=\"content\">\n      <div class=\"graph-info-wrapper ld-body-small\" style=\"margin-bottom:5px\">\n        <div style=\"width: 25%\">\n          <div class=\"_last-modified-by\">{{ 'Modified By ' + (savedGraph?.LastModifiedBy || ' N/A') }}</div>\n          <div class=\"_saved-date\"> {{ savedDate }} </div>\n        </div>\n        <div style=\"width: 100%\">\n          <div type=\"button\"\n              (click)=\"revertDraftToDeployed()\" \n              class=\"ld-tertiary-small-button {{ deployedGraph && !isDraftEqualDeploy && !isEditing ? '' : 'disabled' }} _revert-to-previous-deployment-button\">\n            Restore to Previous Deployment\n          </div>\n        </div>\n        <div>\n          <div id=\"deploy-button\" \n               type=\"button\" \n               (click)=\"clickDeployGraphButton()\" \n               class=\"ld-primary-small-button {{ canDeploy ? '' : 'disabledButton' }} _deploy-button\"\n               title=\"{{ canDeploy ? '' : 'Please save your changes before deploying' }}\">\n            Deploy\n          </div>\n        </div>\n      </div>\n      <div class=\"bu-unit-rules\">\n        <ld-data-table [options]=\"draftTableConfigs\" [data]=\"graphDraft.edges\" class=\"_business-unit-rules-table\">\n          <ng-template secondaryRowContent let-rowData=\"rowData\" let-originalRowData=\"originalRowData\" let-rowIndex=\"rowIndex\">\t\t\n            <div *ngIf=\"rowData.conditions\" class=\"soql-row\">\n              <span class=\"ld-link\" [innerHTML]=\"graphDraftParsedConditions[rowData.name]\"></span>\n              <span *ngIf=\"!isValidEdge[rowData.name]\" class=\"warning-sign triangle_error_icon_form\" style=\"vertical-align: middle; margin-left: 5px;\"></span>\n            </div>\n            <div *ngIf=\"!rowData.conditions\" class=\"soql-row\">\n              <span [ngClass]=\"[rowData.type === 'default' ? '' : 'ld-link _add-conditions-button']\">{{ (rowData.type === 'default' ? 'No Conditions' : 'Add Conditions') }}</span>\n            </div>\n          </ng-template>\n          <ng-template expandableRowContent let-rowData=\"rowData\" let-originalRowData=\"originalRowData\" let-rowIndex=\"rowIndex\">\n            <div id=\"{{ rowData.name }}-{{ objectType }}-business-rule-tuple-table-wrapper\" style=\"display: flex;margin-left: 75px;padding-right: 10px;\">Data</div>\n          </ng-template>\n        </ld-data-table>\n      </div>\n      \n    </ng-template>\n  </p-tabPanel>\n  <p-tabPanel header=\"Deployed\" class=\"_deployed-tab\">\n    <ng-template pTemplate=\"content\">\n      <div class=\"bu-unit-rules\">\n        <ld-data-table [options]=\"deployTableConfigs\" [data]=\"deployedGraph?.graphData.edges\">\n          <ng-template secondaryRowContent let-rowData=\"rowData\" let-originalRowData=\"originalRowData\" let-rowIndex=\"rowIndex\">\t\t\n            <div *ngIf=\"rowData.conditions\" class=\"soql-row\" [innerHTML]=\"deployedGraphParsedConditions[rowData.name]\"></div>\n            <div *ngIf=\"!rowData.conditions\" class=\"soql-row\">No Conditions</div>\n          </ng-template>\n        </ld-data-table>\n      </div>\n      \n    </ng-template>\n  </p-tabPanel>\n</p-tabView>\n");

