/* harmony default export */ __webpack_exports__["default"] = ("<div id=\"deployment-history-wrapper\" class=\"angular-page-wrapper-props ld-body-medium\">\n  <div class=\"ld-header\">{{ pageTitle }}</div>\n  <div class=\"ld-subheader\">Routing Insights & Deployment History</div>\n  <div class=\"ld-header-description\">\n    View all previous deployments of your Graphs{{ routeSObjectType === 'Meeting' ? '' : ' and One-Time Routing runs'}}. \n    Select a deployment to view Routing Insights.</div>\n  <div *ngIf=\"isMultiEnabled else allDeployments\">\n    <p-tabView *ngIf=\"deployedGraphs\" [(activeIndex)]=\"pageSettings.activeTabIndex\">\n      <!--\n        General\n      -->\n      <p-tabPanel\n        header=\"Live Deployments\"\n        class=\"live-deployments-tab-panel\">\n        <ld-data-table *ngIf=\"deployments?.Live && tableConfigs?.Live\"\n        [options]=\"tableConfigs.Live\"\n        [data]=\"deployments.Live\"\n        ></ld-data-table>\n      </p-tabPanel>\n      <!--\n        Marketing Engagements\n      -->\n      <p-tabPanel\n        header=\"All Deployments\"\n        class=\"all-deployments-tab-panel\">\n        <ng-container *ngTemplateOutlet=\"allDeployments\"></ng-container>\n      </p-tabPanel>\n    </p-tabView>\n  </div>\n</div>\n<ng-template #allDeployments>\n  <div class=\"all-deployments-main\">\n    <div class=\"above-table-section\">\n      <div class=\"above-table-dropdowns\">\n        <div *ngIf=\"isMultiEnabled\" class=\"business-unit-section\">\n          Business Unit\n          <div class=\"business-unit-dropdown\">\n            <p-dropdown\n            [(ngModel)]=\"pageSettings.selectedBU\"\n            [options]=\"BUOptions\"\n            (onChange)=\"onSelectBusinessUnit($event)\"\n            styleClass=\"ng-dropdown-small\"\n            placeholder=\"Select Business Unit\"\n            [filter]=\"BUOptions.length > 1\"\n            dropdownIcon=\"down-arrow-icon\">\n            </p-dropdown>\n          </div>\n        </div>\n        <div *ngIf=\"routeSObjectType !== 'Meeting'\" class=\"routing-type-section\">\n          Routing Type\n          <div class=\"routing-type-dropdown\">\n            <p-dropdown\n            [(ngModel)]=\"pageSettings.selectedRoutingType\"\n            [options]=\"routingTypeOptions\"\n            (onChange)=\"onSelectRoutingType($event)\"\n            styleClass=\"ng-dropdown-small\"\n            placeholder=\"Select Routing Type\"\n            dropdownIcon=\"down-arrow-icon\">\n            </p-dropdown>\n          </div>\n        </div>\n      </div>\n      <div class=\"above-table-checkbox\">\n        <div class=\"hide-graphs-checkbox\">\n          <p-checkbox\n          [(ngModel)]=\"pageSettings.hideEmptyGraphs\"\n          (onChange)=\"onHideCheckboxChange($event)\" \n          [binary]=\"true\"\n          styleClass=\"ng-checkbox-small\"\n          [style]=\"{'padding-right': '2px'}\"\n          >\n          </p-checkbox>\n        </div>\n        Hide Graphs with No {{ (routeSObjectType | labelData).pluralLabel || (routeSObjectType | pluralize) }}\n      </div>\n    </div>\n    <div class=\"table-section\">\n      <ld-data-table *ngIf=\"deployments?.All && tableConfigs?.All\"\n      [options]=\"tableConfigs.All\"\n      [data]=\"deployments.All[pageSettings.selectedRoutingType]\"\n      ></ld-data-table>\n    </div>\n  </div>\n</ng-template>\n");

