/* harmony default export */ __webpack_exports__["default"] = ("<div id=\"flowbuilder-editor-wrapper\" class=\"_{{ sObjectType.toLowerCase().split(' ').join('_') }}-flowbuilder-editor\">\n  <div id=\"flowbuilder-editor-header-container\">\n    <!-- Graph Name Display/Editor -->\n    <div class=\"flowbuilder-editor-graph-name\">\n      <svg class=\"leandata-icon\" viewBox=\"0 0 25 25\">\n        <use href='#leandata-logo-icon'></use>\n      </svg>\n      <ld-editable-content\n        *ngIf=\"!isReadOnly && !isRoutingInsightsView\"\n        #graphNameInput\n        class=\"editable-graph-name\"\n        [(value)]=\"graphName\"\n        [maxLength]=\"400\"\n        [validateFunction]=\"validateGraphName.bind(this)\"\n        (valueChange)=\"checkGraphChangedState()\"\n        [pTooltip]=\"graphName\"\n        tooltipPosition=\"bottom\"\n        tooltipStyleClass=\"graph-tooltip\"\n      ></ld-editable-content>\n      <div\n        *ngIf=\"isReadOnly || isRoutingInsightsView\"\n        class=\"graph-name\"\n        [pTooltip]=\"graphName\"\n        tooltipPosition=\"bottom\"\n        tooltipStyleClass=\"graph-tooltip\"\n      >\n        {{ graphName }}\n      </div>\n      <svg *ngIf=\"!isReadOnly && !isRoutingInsightsView\" class=\"edit-icon\" viewBox=\"0 0 10 10\" (click)=\"focusGraphNameInput()\">\n        <use href='#edit-pencil-icon'></use>\n      </svg>\n    </div>\n\n    <div class=\"flowbuilder-editor-graph-controls\">\n      <div class=\"left-control\">\n        <!-- Graph Status -->\n        <div *ngIf=\"!isRoutingInsightsView\" class=\"flowbuilder-editor-status graph-status\" [ngClass]=\"graphStatusClasses\">\n          <div\n            *ngIf=\"isValid && !isValidating\"\n            class=\"graph-status-text-wrapper\"\n          >\n            <div *ngIf=\"graphStatusTextPrimary\" class=\"graph-status-text primary-status-text\">\n              {{ graphStatusTextPrimary }}\n            </div>\n            <div *ngIf=\"graphStatusTextSecondary\" class=\"graph-status-text secondary-status-text\" (click)=\"scheduledJobsModal.toggleModal()\">\n              {{ graphStatusTextSecondary }}\n            </div>\n            <ld-scheduled-jobs-modal\n              #scheduledJobsModal\n              [data]=\"appState.scheduledJobs\"\n              [isGraphView]=\"true\"\n              position=\"right\"\n            >\n            </ld-scheduled-jobs-modal>\n          </div>\n          <div\n            *ngIf=\"!isValid && !isValidating\"\n            class=\"graph-status-icon validation-error-icon validation-error-icon-large\"\n            (click)=\"showValidationErrorMessageModal()\">\n          </div>\n          <p-progressSpinner\n            *ngIf=\"isValidating\"\n            class=\"validation-spinner\"\n            [style]=\"{ width: '20px', height: '20px' }\"\n            strokeWidth=\"6\" \n            animationDuration=\"0.5s\"\n          ></p-progressSpinner>\n        </div>\n        <div *ngIf=\"isRoutingInsightsView\" class=\"flowbuilder-editor-status graph-status-insights\">INSIGHTS</div>\n\n        <!-- Nested Menu -->\n        <button mat-button [matMenuTriggerFor]=\"file\" class=\"file-menu\" type=\"button\">File</button>\n        <mat-menu #file=\"matMenu\">\n          <button\n            mat-menu-item\n            *ngIf=\"!isLive && !isReadOnly && !isRoutingInsightsView\"\n            class=\"file-menu-items save-option\"\n            [class.disabled]=\"disableSave()\"\n            (click)=\"graphSaveHandler()\"\n          >\n            <span class=\"menu-item\">Save</span>\n            <span class=\"save-hint menu-item-hint\">CMD/CTRL S</span>\n          </button>\n          <button\n            mat-menu-item\n            *ngIf=\"isReadOnly && !isRoutingInsightsView\"\n            class=\"file-menu-items save-option\"\n            [class.disabled]=\"!isReadOnly || !boardHasChanged\"\n            (click)=\"saveComment()\"\n          >\n            <span class=\"menu-item\">Save Comment(s)</span>\n          </button>         \n          <button\n            mat-menu-item\n            *ngIf=\"isLive && !isReadOnly\"\n            class=\"file-menu-items save-and-deploy-option\"\n            [class.disabled]=\"disableSave()\"\n            (click)=\"graphSaveHandler()\"\n          >\n            <span class=\"menu-item\">Save & Deploy</span>\n            <span class=\"save-hint menu-item-hint\">CMD/CTRL S</span>\n          </button>\n          <button\n            mat-menu-item\n            *ngIf=\"!isRoutingInsightsView && (isLive || isScheduled || !isLockedForEditing)\"\n            class=\"file-menu-items save-as-option\"\n            [class.disabled]=\"!isLive && !isScheduled && isLockedForEditing\"\n            (click)=\"saveAs()\"\n          >\n            <span>Save as</span>\n          </button>\n          <button\n            mat-menu-item\n            *ngIf=\"isRoutingInsightsView\"\n            class=\"file-menu-items save-deployment-as-option\"\n            (click)=\"saveDeploymentAs()\"\n          >\n            <span>Save a Copy</span>\n          </button>\n          <button\n            mat-menu-item\n            class=\"file-menu-items validate-option\"\n            [class.disabled]=\"isReadOnly || isRoutingInsightsView || !isLockedForEditing\"\n            (click)=\"validateGraph()\"\n          >\n            <span class=\"menu-item\">Validate Graph</span>\n            <span class=\"validate-hint menu-item-hint\">CMD/CTRL G</span>\n          </button>\n          <hr class=\"horizontal-line-separator menu-item-separator\">\n          <button mat-menu-item [matMenuTriggerFor]=\"download\" class=\"file-menu-items download-option\">Download</button>\n          <hr class=\"horizontal-line-separator menu-item-separator\">\n          <button mat-menu-item [matMenuTriggerFor]=\"preferences\" class=\"file-menu-items preferences-option\">Preferences</button>\n          <hr class=\"horizontal-line-separator menu-item-separator\">\n          <button\n            mat-menu-item\n            class=\"file-menu-items close-option\"\n            (click)=\"closeGraph()\"\n          >\n            <span class=\"menu-item\">Close Graph</span>\n          </button>\n        </mat-menu>\n\n        <mat-menu #download=\"matMenu\">\n          <button mat-menu-item class=\"download-menu-items export-graph-option\" (click)=\"exportGraphAsImage()\">\n            Graph Image (png)\n          </button>\n          <button \n            mat-menu-item \n            class=\"download-menu-items download-fields-option\" \n            [class.disabled]=\"!isValid\"\n            (click)=\"downloadListOfFields()\"\n          >\n            Fields Used in Graph (csv)\n          </button>\n        </mat-menu>\n        \n        <mat-menu #preferences=\"matMenu\">\n          <button mat-menu-item class=\"preferences-menu-items gridlines-option\" (click)=\"toggleGridlines()\">\n            <div class=\"menu-item-icon-wrapper\">\n              <svg *ngIf=\"showGridlines\" class=\"menu-item-icon checked-icon\" viewBox=\"0 0 10 10\">\n                <use href=\"#checkmark-icon\"></use>\n              </svg>\n            </div>\n            Display Gridlines\n          </button>\n          <button *ngIf=\"fpService.isFeatureEnabled('FEATURE:ROUTING_PRIORITY') && sObjectType !== 'Meeting'\" mat-menu-item class=\"preferences-menu-items gridlines-option\" (click)=\"toggleShowRoutingPriorityColumn()\">\n            <div class=\"menu-item-icon-wrapper\">\n              <svg *ngIf=\"showRoutingPriorityColumn\" class=\"menu-item-icon checked-icon\" viewBox=\"0 0 10 10\">\n                <use href=\"#checkmark-icon\"></use>\n              </svg>\n            </div>\n            Display Default Priorities\n          </button>\n          <button\n            mat-menu-item\n            class=\"preferences-menu-items thumbnail-option\"\n            [class.disabled]=\"isReadOnly || isRoutingInsightsView\"\n            (click)=\"toggleCreateThumbnail()\"\n          >\n            <div class=\"menu-item-icon-wrapper\">\n              <svg *ngIf=\"createThumbnail && !isReadOnly && !isRoutingInsightsView\" class=\"menu-item-icon checked-icon\" viewBox=\"0 0 10 10\">\n                <use href=\"#checkmark-icon\"></use>\n              </svg>\n            </div>\n            Create Thumbnail on Save\n          </button>\n        </mat-menu>\n\n        <button *ngIf=\"!isReadOnly && !isRoutingInsightsView\" mat-button [matMenuTriggerFor]=\"edit\" class=\"edit-menu\" type=\"button\">Edit</button>\n        <mat-menu #edit=\"matMenu\">\n          <button\n            mat-menu-item\n            class=\"edit-menu-items copy-option\"\n            [class.disabled]=\"disableCopy\"\n            (click)=\"copyNodesWithLinks()\"\n          >\n            <span class=\"menu-item\">Copy</span>\n            <span class=\"copy-hint menu-item-hint\">CMD/CTRL C</span>\n          </button>\n          <button\n            mat-menu-item\n            class=\"edit-menu-items Paste-option\"\n            (click)=\"pasteNodesWithLinks()\"\n          >\n            <span class=\"menu-item\">Paste</span>\n            <span class=\"paste-hint menu-item-hint\">CMD/CTRL V</span>\n          </button>\n          <button\n            mat-menu-item\n            class=\"edit-menu-items delete-option\"\n            [class.disabled]=\"disableDelete\"\n            (click)=\"openDeleteModal()\"\n          >\n            Delete\n            <span class=\"delete-hint menu-item-hint\">DELETE</span>\n          </button>\n        </mat-menu>\n      </div>\n\n      <div class=\"middle-control\">\n        <!-- Copy, Paste nodes with links across graphs -->\n        <div *ngIf=\"!isReadOnly && !isRoutingInsightsView\" class=\"middle-wrapper\">\n          <svg\n            class=\"paint-nodes-icon\"\n            [ngClass]=\"showColorPalette ? 'selected' : ''\"\n            [class.disabled]=\"isNodeDetailPanelOpen || showEscKeyBannerMessage\"\n            viewBox=\"0 0 20 20\"\n            (click)=\"toggleColorPalette()\"\n          >\n            <use [ngStyle]=\"{'color': colorsList[selectedColorIndex]}\" href='#paint-icon'></use>\n          </svg>\n          <div *ngIf=\"showColorPalette\" class=\"color-palette\">\n            <!-- Loop through colors in palette to generate squares -->\n            <div \n                *ngFor=\"let color of colorsList; let i = index\" \n                class=\"color-square\" \n                [ngClass]=\"i === selectedColorIndex ? 'selected' : ''\"\n                [ngStyle]=\"{'background': color}\"\n                (click)=\"selectColor(i)\">\n            </div>\n          </div>\n          <div class=\"vertical-line-separator\"></div>\n          <svg\n            class=\"copy-nodes-icon\"\n            viewBox=\"0 0 20 20\"\n            [class.disabled]=\"disableCopy || isNodeDetailPanelOpen || showEscKeyBannerMessage\"\n            (click)=\"[copyNodesWithLinks(), showCopiedMsg()]\"\n          >\n            <use href='#copy-icon'></use>\n          </svg>\n          <div *ngIf=\"showCopiedMessage\" class=\"copy-link-msg copy-node-with-links\">Copied</div>\n          <div class=\"vertical-line-separator\"></div>\n          <svg\n            class=\"paste-nodes-icon\"\n            viewBox=\"0 0 20 20\"\n            [class.disabled]=\"isNodeDetailPanelOpen || showEscKeyBannerMessage\"\n            (click)=\"pasteNodesWithLinks()\"\n          >\n            <use href='#paste-icon'></use>\n          </svg>\n          <div *ngIf=\"rappidService?.pasteError\" class=\"paste-unsuccessfully-msg\">{{ rappidService.pasteError }}</div>\n          <div class=\"vertical-line-separator\"></div>\n          <svg\n            class=\"delete-nodes-icon\"\n            viewBox=\"0 0 20 20\"\n            [class.disabled]=\"disableDelete || isNodeDetailPanelOpen || showEscKeyBannerMessage\"\n            (click)=\"openDeleteModal()\"\n          >\n            <use href='#delete-icon'></use>\n          </svg>\n        </div>\n\n        <!-- Routing Insights Trigger/Date Range/Metrics -->\n        <div *ngIf=\"isRoutingInsightsView\" class=\"middle-wrapper routing-insights-middle-wrapper\">\n          <!-- Trigger -->\n          <div *ngIf=\"deploymentRoutingType === 'Continuous'\" class=\"insights-filter-wrapper insights-trigger-filter-wrapper insights-filter-dropdown\">\n            <span class=\"ld-field-label-small insight-control-label\">Trigger</span>\n            <p-dropdown\n              class=\"trigger-dropdown\"\n              [(ngModel)]=\"selectedStatTypeOption\"\n              [options]=\"statTypeOptions\"\n              (onChange)=\"refreshInsights(hideMetrics, false)\"\n              [ngClass]=\"['stat-type-dropdown']\"\n              styleClass=\"ng-dropdown-small\"\n              optionLabel=\"label\"\n              dropdownIcon=\"down-arrow-icon\"\n            ></p-dropdown>\n          </div>\n          <!-- Date Range -->\n          <div *ngIf=\"deploymentRoutingType === 'Continuous' || deploymentRoutingType === 'API Graph'\" class=\"insights-filter-wrapper insights-date-filter-wrapper\">\n            <span class=\"ld-field-label-small insight-control-label calendar-dates-label\">Dates</span>\n            <p-calendar\n              class=\"start-date\"\n              [(ngModel)]=\"filterStartDate\"\n              [ngClass]=\"['insights-calendar']\"\n              [minDate]=\"minFilterDate\"\n              [maxDate]=\"filterEndDate\"\n              (onSelect)=\"refreshInsights(hideMetrics, false)\"\n              dateFormat=\"yy-mm-dd\"\n            ></p-calendar>\n            <span class=\"ld-field-label-small insight-control-label calendar-to-label\">to</span>\n            <p-calendar\n              class=\"end-date\"\n              [(ngModel)]=\"filterEndDate\"\n              [ngClass]=\"['insights-calendar']\"\n              [minDate]=\"minFilterDate\"\n              [maxDate]=\"maxFilterDate\"\n              (onSelect)=\"refreshInsights(hideMetrics, false)\"\n              dateFormat=\"yy-mm-dd\"\n            ></p-calendar>\n          </div>\n          <!-- One time Routing -->\n          <div *ngIf=\"deploymentRoutingType === '1x Routing'\" class=\"insights-filter-wrapper insights-run-list-wrapper insights-filter-dropdown\">\n            <span class=\"ld-field-label-small insight-control-label one-time-run-label\">One-Time Run</span>\n            <p-dropdown\n              class=\"one-time-run-dropdown\"\n              [(ngModel)]=\"selectedOneTimeRoutingRunOption\"\n              [options]=\"oneTimeRoutingRunsList\"\n              (onChange)=\"handleOneTimeRunChange($event)\"\n              [ngClass]=\"['one-time-run-dropdown']\"\n              styleClass=\"ng-dropdown-small\"\n              optionLabel=\"label\"\n              dropdownIcon=\"down-arrow-icon\"\n            ></p-dropdown>\n          </div>\n          <!-- Scheduled Routing -->\n          <div *ngIf=\"deploymentRoutingType === 'Scheduled Routing'\" class=\"insights-filter-wrapper insights-scheduled-runs-wrapper\">\n            <span class=\"ld-field-label-small\">Trigger:</span>\n            <span class=\"ld-body-medium\" style=\"margin-left: 5px;\">{{ scheduledRunTriggerType }}</span>\n          </div>\n          <div *ngIf=\"deploymentRoutingType === 'Scheduled Routing'\" class=\"insights-filter-wrapper insights-scheduled-runs-wrapper\">\n            <span class=\"ld-field-label-small\">Run Dates</span>\n            <p-multiSelect\n              [(ngModel)]=\"selectedScheduledRuns\"\n              [options]=\"runHistoryList\"\n              [filter]=\"false\"\n              [ngStyle]=\"{'margin-left': '10px', 'width': '210px'}\"\n              styleClass=\"ng-multiselect-dropdown-xtra-small\"\n              dropdownIcon=\"down-arrow-icon\"\n              optionLabel=\"label\"\n              maxSelectedLabels=\"0\"\n              (onPanelHide)=\"handleScheduledRunsDropdownChange()\"\n            >\n              <ng-template let-value pTemplate=\"selectedItems\">\n                <span *ngIf=\"!value || value.length === 0\">None Selected</span>\n                <span *ngIf=\"value && value.length === 1\">{{ value[0].label }}</span>\n                <span *ngIf=\"value && value.length > 1 && value.length !== runHistoryList.length\">\n                  {{ value.length }} Dates Selected\n                </span>\n                <span *ngIf=\"value && value.length > 1 && value.length === runHistoryList.length\">\n                  All Run Dates\n                </span>\n              </ng-template>\n              <p-header class=\"select-all-header-text\">\n                {{ selectedScheduledRuns?.length === runHistoryList?.length ? 'Deselect' : 'Select' }} All\n              </p-header>\n            </p-multiSelect>\n          </div>\n          <!-- Metrics -->\n          <div class=\"insights-filter-wrapper insights-metrics-toggle-wrapper\">\n            <p-checkbox\n              class=\"metrics-checkbox\"\n              [(ngModel)]=\"hideMetrics\"\n              (onChange)=\"refreshInsights($event, true)\"\n              [binary]=\"true\"\n              styleClass=\"ng-checkbox-small\"\n              label=\"Hide Metrics\"\n            ></p-checkbox>\n          </div>\n        </div>\n      </div>\n    \n      <div class=\"right-control\">\n        <!-- Graph Zoom -->\n        <div class=\"zoom-controls\">\n          <div class=\"zoom-button zoom-out-button minus-icon\" [class.disabled]=\"zoomLevel < 0.51\" (click)=\"zoomOut()\"></div>\n          <p-slider\n            class=\"zoom-slider\"\n            [(ngModel)]=\"zoomLevel\"\n            (onChange)=\"zoomSliderChangeHandler($event)\"\n            [min]=\"0.5\"\n            [max]=\"1.5\"\n            [step]=\"0.1\"\n            [animate]=\"true\"\n          ></p-slider>\n          <div class=\"zoom-button zoom-in-button plus-icon\" [class.disabled]=\"zoomLevel >= 1.5\" (click)=\"zoomIn()\"></div>\n        </div>\n    \n        <div class=\"vertical-line-separator\"></div>\n    \n        <!-- Graph Search -->\n        <div class=\"search-wrapper\" (click)=\"[op.toggle($event), onOpenSearchPanel()]\">\n          <svg class=\"search-icon\" viewBox=\"0 0 20 20\">\n            <use href='#search-magnifier-icon'></use>\n          </svg>\n          <p-overlayPanel\n            #op\n            class=\"search-overlay-panel\"\n            styleClass=\"flowbuilder-search-overlay-panel\"\n            [style]=\"{ 'border-radius': '5px', 'margin': '4px 0 0 -2px' }\"\n            appendTo=\"body\"\n          >\n            <div class=\"node-search-wrapper\">\n              <input\n                #searchInput\n                type=\"text\"\n                class=\"graph-search-input ld-input-small\"\n                style=\"width: 150px;\"\n                (input)=\"handleSearchInputChange(searchInput.value)\"\n                autocomplete=\"chrome-off\"\n                placeholder=\"Search\"\n                (keyup.enter)=\"findNode(searchInput.value)\"\n              />\n              <div class=\"node-search-button ld-tertiary-small-button\" (click)=\"findNode(searchInput.value)\">Find</div>\n            </div>\n          </p-overlayPanel>\n        </div>\n\n        <div class=\"vertical-line-separator\"></div>\n\n        <!-- Toolbar Comment -->\n        <div *ngIf=\"!fromOverlord\" class=\"toolbar-comment-wrapper\" [class.disabled]=\"commentService.isFetchingComment\" (click)=\"openToolbarCommentPanel()\">\n          <svg class=\"toolbar-comment-icon\" [class.open-panel]=\"commentService.isToolbarCommentPanelOpen\" viewBox=\"0 0 24 23.2\">\n            <use href='#toolbar-comment-icon'></use>\n          </svg>\n          <div\n            *ngIf=\"!commentService.isFetchingComment\"\n            class=\"toolbar-comment-number\"\n            [class.open-panel]=\"commentService.isToolbarCommentPanelOpen\"\n          >\n            {{ commentService.commentCount }}\n          </div>\n          <p-progressSpinner\n            *ngIf=\"commentService.isFetchingComment\"\n            class=\"loading-comments\"\n            strokeWidth=\"8\"\n            animationDuration=\"1.5s\"\n          ></p-progressSpinner>\n\n          <div\n            *ngIf=\"commentService.isFetchingComment\"\n            class=\"comment-loading-tooltip\"\n            pTooltip=\"Loading comments\"\n            tooltipPosition=\"left\"\n            tooltipStyleClass=\"graph-tooltip\"\n          ></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div\n    *ngIf=\"commentService.isToolbarCommentPanelOpen\"\n    id=\"fb-toolbar-comment-panel\"\n  >\n    <ld-toolbar-comment-panel\n      [isRoutingInsightsView]=\"isRoutingInsightsView\"\n      (panelCloseEventHandler)=\"closeToolbarCommentPanel()\"\n    ></ld-toolbar-comment-panel>\n  </div>\n\n  <!-- Delete modal backdrop -->\n  <div *ngIf=\"appState.showConfirmationDialogBackdrop || showDialogBackdrop\" class=\"dialog-backdrop\"></div>\n\n  <!-- Read only Banner messages -->\n  <ng-container *ngIf=\"!fromOverlord\">\n    <div *ngIf=\"isReadOnly && !isRoutingInsightsView\" class=\"view-only-message-banner\">\n      VIEW ONLY\n      <span *ngIf=\"graphEditedByName\" class=\"editor-message-banner-text\"> - <i>{{ graphEditedByName }}</i> is currently editing this graph.</span>\n    </div>\n    <div *ngIf=\"!isLockedForEditing && !isReadOnly && !isRoutingInsightsView && !isSameUser\" class=\"view-only-message-banner highlighted\">\n      <p><i><b>{{ graphEditedByName }}</b></i> is now editing this graph.</p>\n    </div>\n    <div *ngIf=\"isLockedForEditing && containsNonUpgradedNodes && !isRoutingInsightsView\" class=\"view-only-message-banner highlighted\">\n      <p><b>Unable to {{ isLive ? 'Save &amp; Deploy' : 'Deploy' }}:</b> This graph contains nodes unavailable in your package. Upgrade or remove unsupported nodes to deploy. <a href=\"https://leandata.com/pricing\" target=\"_blank\">Learn more</a>.</p>\n    </div>\n  </ng-container>\n  <!-- Routing Insights Banner messages -->\n  <div *ngIf=\"isRoutingInsightsView && deploymentRoutingType === 'Scheduled Routing'\" class=\"routing-insights-message-banner\">\n    This is a retrospective view of records processed after the scheduled run(s) were complete. Insights may be delayed.\n  </div>\n  <div *ngIf=\"isRoutingInsightsView && deploymentRoutingType !== 'Scheduled Routing'\" class=\"routing-insights-message-banner\">\n    This is a retrospective view of records processed when this graph was live. Insights may be delayed.\n  </div>\n  <!-- Flowbuilder ESC Key Banner messages -->\n  <div *ngIf=\"showEscKeyBannerMessage\" class=\"additional-info-message-banner esc-banner\">\n    Press the ESC key to return to node properties.\n  </div>\n\n  <!-- Paper part -->\n  <div\n    #graphEditorBoard\n    id=\"graph-editor-board\"\n    class=\"editor-board\"\n    [class.read-only-graph]=\"isReadOnly\"\n  >\n    <!-- Edge selection menu wrapper -->\n    <div #edgeSelectionMenu\n      id=\"edge-selection-menu-wrapper\"\n      class=\"edge-selesciton-menu\"\n      [hidden]=\"!(edgeMenuList?.length > 0)\"\n      [style.top]=\"edgeMenuLocation?.top\"\n      [style.left]=\"edgeMenuLocation?.left\"\n    >\n      <div *ngIf=\"!isReadOnly\">\n        <div *ngFor=\"let edge of edgeMenuList\" class=\"edge-menu-item\" (mousedown)=\"onEdgeMenuItemMouseDown($event, edge)\">\n          {{ edge.name | formatEdgeName }}\n        </div>\n      </div>\n      <div *ngIf=\"isReadOnly\">\n        <div\n            *ngFor=\"let edge of edgeMenuList\"\n            class=\"edge-menu-item\"\n            style=\"color: var(--med-grey-1)\"\n            pTooltip=\"Unable to select edges in View/Comment mode\"\n            tooltipPosition=\"right\"\n            tooltipStyleClass=\"graph-tooltip\">\n              {{ edge.name | formatEdgeName }}\n        </div>\n      </div>\n    </div>\n\n    <!-- Delete node confirmation panel -->\n    <div\n      *ngIf=\"openDeletePanel\"\n      class=\"delete-node-confirmation-panel\"\n      [style.top]=\"deleteNodePanelLocation?.top\"\n      [style.left]=\"deleteNodePanelLocation?.left\"\n    >\n      <div class=\"delete-cancel\" (click)=\"openDeletePanel = false\">\n        <i class=\"pi pi-times\"></i>\n        <div class=\"delete-panel-tooltip cancel-tooltip\">Cancel</div>\n      </div>\n      <div class=\"delete-confirm\" (click)=\"deleteNodes()\">\n        <i class=\"pi pi-check\"></i>\n        <div class=\"delete-panel-tooltip confirm-tooltip\">Delete</div>\n      </div>\n    </div>\n\n    <!-- Node Menu -->\n    <ld-node-stencil-menu\n      #nodeStencilMenu\n      *ngIf=\"!isRoutingInsightsView\"\n      class=\"node-stencil-menu\"\n      [sObjectType]=\"sObjectType\"\n      [selectedColor]=\"colorsList[selectedColorIndex]\"\n      [isReadOnly]=\"isReadOnly\"\n      [fieldMetaDataMap]=\"fieldsMetaDataMap\"\n      [fromOverlord]=\"fromOverlord\"\n      (onNodeMouseDown)=\"onNodeMenuItemMouseDown($event)\"\n      (showBackdropOnPanelClose)=\"addDialogBackdrop()\"\n      (removeBackdropOnPanelClose)=\"removeDialogBackdrop()\"\n    ></ld-node-stencil-menu>\n\n    <!-- Routing Insights Metrics Legend Overlay -->\n    <div *ngIf=\"isRoutingInsightsView\" class=\"metrics-legend\">\n      <div class=\"metrics-legend-row legend-success\">\n        <svg>\n          <circle cx=\"15\" cy=\"15\" r=\"15\" class=\"fill-green\"/>\n        </svg>\n        <span>Action Success</span>\n        <div class=\"hover-tip\">\n          Number of {{ sObjectType | sObjLabel | pluralize }} successfully processed within the action node {{ sObjectType === 'Lead' ? '(e.g. lead owner routed and assigned to matched account owner)' : '' }}\n        </div>\n      </div>\n      <div class=\"metrics-legend-row legend-failure\">\n        <svg>\n          <circle cx=\"15\" cy=\"15\" r=\"15\" class=\"fill-red\"/>\n        </svg>\n        <span> Action Failure </span>\n        <div class=\"hover-tip\">\n          Number of {{ sObjectType | sObjLabel | pluralize }} unsuccessfully processed within the action node {{ sObjectType === 'Lead' ? '(e.g. attempt to convert a queue owned lead)' : '' }}\n        </div>\n      </div>\n      <div class=\"metrics-legend-row legend-success-failure\">\n        <svg>\n          <circle cx=\"15\" cy=\"15\" r=\"15\" class=\"fill-green\"/>\n          <path d=\"M0,15 a1,1 0 0,0 30,0\" class=\"fill-red\"/>\n          <line stroke=\"white\" stroke-width=\"2\" x1=\"0\" x2=\"30\" y1=\"15\" y2=\"15\" />\n        </svg>\n        <span>Action Success / Failure</span>\n        <div class=\"hover-tip\">\n          Indicates that a particular action node has both {{ sObjectType | sObjLabel | pluralize }} successfully processed as well as {{ sObjectType | sObjLabel | pluralize }} that were unsuccessfully processed\n        </div>\n      </div>\n      <div *ngIf=\"sObjectType !== 'Meeting'\" class=\"metrics-legend-row legend-pending\">\n        <svg>\n          <circle cx=\"15\" cy=\"15\" r=\"15\" class=\"fill-orange\"/>\n        </svg>\n        <span>Pending</span>\n        <div class=\"hover-tip\">\n          Number of {{ sObjectType | pluralize }} that are pending to continue processing through Router at this point\n        </div>\n      </div>\n      <div class=\"metrics-legend-row legend-eof\">\n        <svg viewBox=\"40 0 80 110\">\n          <polygon class=\"fill-blue\" points=\"50,5 105,5 130,35 130,75 105,105 50,105 25,75 25,35\"/>\n        </svg>\n        <span>End of Flow</span>\n        <div class=\"hover-tip\">\n          Number of {{ sObjectType | sObjLabel | pluralize }} that ended their processing through Router at this point\n        </div>\n      </div>\n    </div>\n\n    <!-- Main rappid paper container -->\n    <div\n      #paperContainer \n      id=\"paper-container\"\n      class=\"main-paper-container\"\n      [ngClass]=\"[isRoutingInsightsView ? 'routing-insights-view' : '']\"\n    >\n      <div\n        *ngIf=\"flowbuilderService.hoverCardPosition\"\n        [style.left.px]=\"flowbuilderService.hoverCardPosition.left\"\n        [style.top.px]=\"flowbuilderService.hoverCardPosition.top\"\n        [ngClass]=\"['hover-card', flowbuilderService.cardClass]\"\n      >\n        <!-- TODO: might be able to utilize some rappid.js functionality for hover cards here for Comment Node V2 -->\n        <!-- These can be triggered from the nodeModel/nodeView itself with rappid -->\n        <div *ngIf=\"flowbuilderService.hoverCardContent\" class=\"hover-card-content\">{{ flowbuilderService.hoverCardContent }}</div>\n        <div *ngIf=\"!flowbuilderService.hoverCardContent\" class=\"hover-card-content\"><i>No Comment</i></div>\n      </div>\n      \n      <div\n        *ngIf=\"flowbuilderService.commentPosition\"\n        [style.left.px]=\"flowbuilderService.commentPosition.left\"\n        [style.top.px]=\"flowbuilderService.commentPosition.top\"\n        [ngClass]=\"['hover-card', 'comment-text']\"\n      >\n        <div *ngIf=\"flowbuilderService.commentContent\" class=\"hover-card-content\">{{ flowbuilderService.commentContent }}</div>\n        <div *ngIf=\"!flowbuilderService.commentContent\" class=\"hover-card-content\"><i>No Comment</i></div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Node editor side panel overlays -->\n  <div\n    *ngIf=\"isNodeDetailPanelOpen || commentService.isToolbarCommentPanelOpen\" \n    id=\"node-editor-backdrop\"\n    [class.comment-panel]=\"commentService.isToolbarCommentPanelOpen\" \n    (click)=\"triggerClosePanelAction()\"\n  ></div>\n  <div\n    id=\"node-editor-sidebar\"\n    [@drawerSlideInOut]=\"isNodeDetailPanelOpen ? 'drawerSlideIn' : 'drawerSlideOut'\">\n    <ld-node-editor\n      #nodeEditor\n      class=\"node-editor-wrapper\"\n      [fromOverlord]=\"fromOverlord\"\n      [nodeModel]=\"nodeModelToEdit\"\n      [isReadOnly]=\"isReadOnly\"\n      [isRoutingInsightsView]=\"isRoutingInsightsView\"\n      [sObjectType]=\"sObjectType\"\n      [allNodeNamesSet]=\"allNodeNamesSet\"\n      [zoomInfoNodeNamesMap]=\"zoomInfoNodeNamesMap\"\n      [holdUntilNodeNamesMap]=\"holdUntilNodeNamesMap\"\n      [nodeNamesToNodesMap]=\"nodeNamesToNodesMap\"\n      [fieldsMetaData]=\"fieldsMetaData\"\n      [fieldsMetaDataMap]=\"fieldsMetaDataMap\"\n      [actionNodeMetaData]=\"actionNodeMetaData\"\n      [variablesHandler]=\"variablesHandler\"\n      (panelCloseEventHandler)=\"[closeNodeEditor($event), removeDialogBackdrop()]\"\n      (showBackdropOnPanelClose)=\"addDialogBackdrop()\"\n      (removeBackdropOnPanelClose)=\"removeDialogBackdrop()\"\n    ></ld-node-editor>\n  </div>\n\n  <p-dialog\n    [modal]=\"true\"\n    [(visible)]=\"inactiveDialogVisible\"\n    [closable]=\"false\"\n    [resizable]=\"false\"\n    [draggable]=\"false\">  \n    <p-header [ngSwitch]=\"modalOptions.messageTemplate\">\n      <div *ngSwitchCase=\"'over15Min'\">Still Editing?</div>\n      <div *ngSwitchCase=\"'over1Hour'\">Session Unlock Warning</div>\n      <div *ngSwitchCase=\"'lostEditing'\">Another User is Editing this Graph</div>\n    </p-header>\n\n    <div class=\"ui-confirmdialog-message\" [ngSwitch]=\"modalOptions.messageTemplate\">\n      <div *ngSwitchCase=\"'over15Min'\">\n        <div>You have been inactive for <b>15 minutes</b>.</div>\n        <br/>\n        <div>For your security, Salesforce may automatically log you out and erase all of your unsaved changes.</div>\n      </div>\n      <div *ngSwitchCase=\"'over1Hour'\">\n        <div>You have been inactive for <b>1 hour</b>.</div> \n        <br/>\n        <div>\n          If you remain inactive until <b> {{ modalOptions.timeLapsed }}</b>, LeanData will unlock this graph for others to edit.\n          <ld-tooltip class=\"inline-tooltip-wrapper\" [content]=\"inactiveTooltipContent\"> </ld-tooltip>\n        </div>\n      </div> \n      <div *ngSwitchCase=\"'lostEditing'\">\n        <div>You have been inactive.</div>\n        <br/>\n        <i>{{ modalOptions.editedByName }}</i> is now editing the graph. Any changes you make will be saved as a new graph.\n      </div>\n    </div>\n\n    <p-footer>\n      <div\n        *ngIf=\"modalOptions.showRejectButton\"\n        class=\"ng-dialogCancelButton\"\n        type=\"button\"\n        (click)=\"modalOptions.onCancel()\"\n      >\n        {{ modalOptions.cancelButtonText }}\n      </div>\n      <div type=\"button\"\n        (click)=\"modalOptions.onConfirm()\"\n        class = \"ng-dialogConfirmButton\">\n        {{ modalOptions.confirmButtonText }}\n      </div>\n    </p-footer>\n  </p-dialog>\n  \n  <!-- Error modal for displaying validation errors -->\n  <ld-graph-errors-modal class=\"graph-error-modal\" [errorModalData]=\"errorModalData\" (confirm)=\"removeDialogBackdrop()\"\n  (openNodeEmitter)=\"openNodeEditor($event)\"></ld-graph-errors-modal>\n</div>\n");

