/* harmony default export */ __webpack_exports__["default"] = ("<div class=\"angular-page-wrapper-props\">\n  \n  <div id=\"flowbuilder-graphs-header-row\">\n    <div>\n      <div class=\"ld-header _flowbuilder-object-header\">{{ pageTitle || (sObjectType | labelData).pluralLabel }}</div>\n      <div class=\"ld-subheader\">FlowBuilder</div>\n      <div class=\"ld-header-description _flowbuilder-description\">Create and manage all of your {{ (pageTitle === 'BookIt for Forms' ? 'BookIt' : pageTitle) || (sObjectType | labelData).label }}{{ pageTitle ? '' : ' Routing' }} Graphs. Only one Graph can be live at a time.</div>\n    </div>\n  </div>\n\n  <!-- Main Graph/Tab Views -->\n  <ng-container *ngIf=\"sObjectType !== 'Meeting' && multiGraphEnabled; then tabView; else standardView\"></ng-container>\n  <ng-template #tabView>\n    <p-tabView\n        [ngClass]=\"{'nonborder-tabview' : isAnyObject}\"\n        [activeIndex]=\"selectedTabIndex\"\n        (onChange)=\"changeGraphTypeTab($event.index)\"\n        styleClass=\"tab-content-vertical _graphs-tab-view\">\n\n      <p-tabPanel \n          *ngIf=\"!isAnyObject\"\n          [disabled]=\"tileViewSettings?.businessUnits?.length == 0 || isFetchingData\"  \n          headerStyleClass=\"ui-tabview-title _business-unit-tab\">\n        <ng-template pTemplate=\"header\">\n          Business Unit <span *ngIf=\"tileViewSettings?.multiGraphOn\" class=\"ld-badge-small _bu-on-label\">ON</span>\n        </ng-template>\n        <ng-template pTemplate=\"content\">\n          <ng-container *ngTemplateOutlet=\"fbGraphsActionRow; context: { isBusinessUnitTab: true }\"></ng-container>\n          <ng-container *ngTemplateOutlet=\"fbGraphTiles; context: { tiles: graphsToBUDisplay[selectedBUId] }\"></ng-container>\n        </ng-template>\n      </p-tabPanel>\n      <p-tabPanel \n          [disabled]=\"!tileViewSettings?.isLDAdmin || isFetchingData\" \n          headerStyleClass=\"ui-tabview-title _single-graph-tab\">\n        <ng-template pTemplate=\"header\">\n          {{ isAnyObject ? '' : 'Single Graph'}} <span *ngIf=\"!isAnyObject && !tileViewSettings?.multiGraphOn\" class=\"ld-badge-small _graph-on-label\"> ON </span>\n        </ng-template>\n        <ng-template pTemplate=\"content\">\n          <ng-container *ngTemplateOutlet=\"fbGraphsActionRow; context: { isBusinessUnitTab: false }\"></ng-container>\n          <ng-container *ngTemplateOutlet=\"fbGraphTiles; context: { tiles: singleGraphs }\"></ng-container>\n        </ng-template>\n      </p-tabPanel>\n    </p-tabView>\n  </ng-template>\n  <ng-template #standardView>\n    <ng-container *ngTemplateOutlet=\"fbGraphsActionRow; context: { isBusinessUnitTab: false }\"></ng-container>\n    <ng-container *ngTemplateOutlet=\"fbGraphTiles; context: { tiles: singleGraphs }\"></ng-container>\n  </ng-template>\n\n  <!-- Action Row Reusable Template -->\n  <ng-template #fbGraphsActionRow let-buTab=\"isBusinessUnitTab\">\n    <div id=\"flowbuilder-graphs-action-row\" class=\"ld-body-medium\">\n\n      <div class=\"flowbuilder-graphs-action-col\">\n        <div class=\"ld-secondary-small-button _create-graph-btn\" [class.disabled]=\"isFetchingData\" (click)=\"navigateToGraphEdit()\">Create Graph</div>\n        <p-fileUpload #importFlowUploader\n            [auto]=\"true\"\n            (uploadHandler)=\"[importFlow($event.files[0]), importFlowUploader.clear()]\"\n            styleClass=\"action-button-style ld-tertiary-small-button _import-graph-btn {{isFetchingData?'disabled':''}}\"\n            customUpload=\"true\"\n            chooseLabel=\"Import Graph\"\n            chooseIcon=\"\"\n            [class.disabled]=\"isFetchingData\" \n            [disabled]=\"isFetchingData\"\n            mode=\"basic\"\n            title=\"\">\n        </p-fileUpload>\n      </div>\n\n      <div *ngIf=\"buTab\" class=\"flowbuilder-graphs-action-col _bu-filter-section\">\n        <ul class=\"bu-filter-label-wrapper\">\n          <li class=\"ld-field-label-small\" >Business Unit</li>\n          <li (click)=\"showBuConditionsModal()\" [class.disabled]=\"isFetchingData\" class=\"ld-link _bu-conditions-link ld-body-small\">Conditions</li>\n        </ul>\n        <ld-typeahead\n            #searchBusinessUnit\n            [(selections)]=\"buTypeaheadSelection\"\n            [searchFunction]=\"searchBusinessUnits\"\n            (onSelect)=\"onSelectBU($event)\"\n            [filter]=\"filterBUSuggestions\"\n            placeholder=\"Select a Business Unit\"\n            style=\"width: 250px\"\n            [disabled]=\"isFetchingData\"\n          ></ld-typeahead>\n          <hr class=\"ld-seperator\" >\n        <div class=\"ld-link refresh-button\" [class.disabled]=\"isFetchingData\" (click)=\"refreshGraphs()\">Refresh Graphs</div>\n      </div>\n\n      <div *ngIf=\"!buTab\" class=\"ld-link refresh-button\" [class.disabled]=\"isFetchingData\" (click)=\"refreshGraphs()\">Refresh Graphs</div>\n    </div>\n  </ng-template>\n\n  <!-- Graph Tiles Reusable Template -->\n  <ng-template #fbGraphTiles let-tiles=\"tiles\">\n    <div *ngIf=\"tiles?.liveScheduled\" class=\"graph-tiles-wrapper\">\n      <div class=\"graph-tile-section-header ld-section-header\">Live{{ sObjectType === 'Meeting' ? '' : ' & Scheduled'}}</div>\n      <div *ngIf=\"isFetchingData\" class=\"loading-graphs\">\n        <p-progressSpinner\n          [style]=\"{width: '40px', height: '40px'}\"\n          strokeWidth=\"4\" \n          animationDuration=\"1.5s\"\n        ></p-progressSpinner>\n        <div class=\"loading-text\">Loading Graphs...</div>\n      </div>\n      <div class=\"ld-body-large\" *ngIf=\"noLiveText && !isFetchingData\" style=\"margin-bottom: 10px\">\n        {{noLiveText}}\n      </div>\n      <div class=\"grid\" *ngIf=\"!isFetchingData\">\n        <ld-graph-tile\n            *ngFor=\"let graphTile of tiles?.liveScheduled\"\n            [graphTile]=\"graphTile\"\n            class=\"grid-item _graph-tile-{{graphTile.id}}\"\n            [style.z-index]=\"selectedGraphTileId === graphTile.id ? 4 : null\"\n            [parentEventEmitter]=\"tileEventEmitter\"\n            (tileDoubleClick)=\"navigateToGraphEdit($event)\"\n            (tileActionClick)=\"tileActionHandler($event)\">\n        </ld-graph-tile>\n      </div>\n    </div>\n\n    <div *ngIf=\"tiles?.draft\" class=\"graph-tiles-wrapper\">\n      <div class=\"graph-tile-section-header ld-section-header\">Drafts</div>\n        <div *ngIf=\"isFetchingData\" class=\"loading-graphs\">\n          <p-progressSpinner\n            [style]=\"{width: '40px', height: '40px'}\"\n            strokeWidth=\"4\" \n            animationDuration=\"1.5s\"\n          ></p-progressSpinner>\n          <div class=\"loading-text\">Loading Graphs...</div>\n        </div>\n      <div class=\"ld-body-large\" *ngIf=\"noDraftsText && !isFetchingData\">\n        {{noDraftsText}}\n      </div>\n      <div class=\"grid\" *ngIf=\"!isFetchingData\">\n        <ld-graph-tile\n            *ngFor=\"let graphTile of tiles?.draft\"\n            [graphTile]=\"graphTile\"\n            class=\"grid-item _graph-tile-{{graphTile.id}}\"\n            [style.z-index]=\"selectedGraphTileId === graphTile.id ? 4 : null\"\n            (tileDoubleClick)=\"navigateToGraphEdit($event)\"\n            (tileActionClick)=\"tileActionHandler($event)\">\n        </ld-graph-tile>\n      </div>\n    </div>\n  </ng-template>\n\n  <!-- General modal for showing graph errors -->\n  <ld-graph-errors-modal \n    (confirm)=\"errorModalConfirmHandler($event)\" \n    [errorModalData]=\"errorModalData\" \n    [importGraphData]=\"importGraphData\">\n  </ld-graph-errors-modal>\n  \n  <p-dialog\n    [(visible)]=\"deployModalParams.showDeployModal\"\n    [modal]=\"true\"\n    [closable]=\"true\"\n    [resizable]=\"false\"\n    [draggable]=\"false\"\n  >\n    <p-header>{{deployModalParams.deployModalHeaderText}}</p-header>\n    <div class=\"ld-body-large\">\n        <div *ngIf=\"(routingPriorityProvisioned && deployModalParams.selectedGraphTile.hasRoutingPriorities) && (!orgData.ccioPrioritizationEnabled || deployModalParams.showPostDeployMessage)\" \n          class=\"warning-note light-warning deploy-warning-note\" \n        >\n          <div class=\"alert-icon\" style=\"margin-right:8px;flex:1 1 25px;\"></div>\n          <div>\n            <ng-container *ngIf=\"deployModalParams.showPostDeployMessage; then postDeployWarning; else preDeployWarning\"></ng-container>\n            <ng-template #preDeployWarning><b>Routing Prioritization is disabled.</b><br></ng-template>\n            <ng-template #postDeployWarning>\n              <b>Graph deployed with Routing Prioritization {{(orgData.ccioPrioritizationEnabled ? 'enabled' : 'disabled')}}</b>\n              <br>\n            </ng-template>\n            \n            {{deployModalParams.deployModalWarningText}}\n            <a href=\"/apex/Dashboard#admin/settings/routing_priority\" target=\"_blank\" class=\"hoverLink\">Routing Prioritization</a> is enabled.\n          </div>\n        </div>\n        <ng-container *ngIf=\"deployModalParams.showPostDeployMessage; then postDeployMessage; else preDeployMessage\"></ng-container>\n        <ng-template #postDeployMessage>Graph deployed: {{deployModalParams.selectedGraphTile.name}}</ng-template>\n        <ng-template #preDeployMessage>Please confirm you would like to deploy this graph: {{deployModalParams.selectedGraphTile.name}}</ng-template>\n    </div>\n    <p-footer>\n      <ng-container *ngIf=\"deployModalParams.showPostDeployMessage; then postDeployButtons; else preDeployButtons\"></ng-container>\n      <ng-template #preDeployButtons>\n        <div type=\"button\" (click)=\"deployModalParams.showDeployModal = false;\" class=\"ng-dialogCancelButton\">\n          Cancel\n        </div>\n        <div type=\"button\" (click)=\"validateGraphBeforeDeploy(deployModalParams.selectedGraphTile)\" class=\"ng-dialogConfirmButton\">\n          OK\n        </div>\n      </ng-template>\n      <ng-template #postDeployButtons>\n        <div type=\"button\" (click)=\"deployModalParams.showDeployModal = false;this.fetchData();\" class=\"ng-dialogConfirmButton\">\n          OK\n        </div>\n      </ng-template>\n    </p-footer>\n  </p-dialog>\n</div>\n");

