/* harmony default export */ __webpack_exports__["default"] = ("<div\n    data-id=\"{{graphTile.id}}\"\n    [ngClass]=\"tileClasses\"\n    [class.disable-hover-style]=\"disableTileHoverStyle()\"\n    class=\"flowbuilder-graph-tile _graph-tile\"\n    (dblclick)=\"tileDoubleClickHandler(graphTile, $event)\">\n\n  <!-- Graph Info (name, image, dates, info) -->\n  <div class=\"graph-info-column ld-body-medium\">\n    <!-- Live Graph Tile -->\n    <ng-container *ngIf=\"graphTile.isLive; else draftTile\">\n      <ng-container *ngIf=\"graphTile.isReadyToGoLive; else liveIcon\">\n        <div class=\"fb-tile-badge-wrapper rtgl-badge-wrapper\">\n          <div class=\"status-text-badge\">Ready to Go Live</div>\n          <ng-container *ngTemplateOutlet=\"tileBadgeTemplate; context: { tile: graphTile }\"></ng-container>\n        </div>\n      </ng-container>\n      <ng-template #liveIcon>\n        <div class=\"fb-tile-badge-wrapper live-badge-wrapper\">\n          <div class=\"status-text-badge\"><div class=\"live-circle\"></div>LIVE</div>\n          <ng-container *ngTemplateOutlet=\"tileBadgeTemplate; context: { tile: graphTile }\"></ng-container>\n        </div>\n      </ng-template>\n\n      <div class=\"tile-image-wrapper\">\n        <img *ngIf=\"graphTile.image\" [src]=\"graphTile.image\" class=\"tile-image-large _tile-image-large\">\n      </div>\n\n      <div class=\"hover-button-items-row\">\n        <ng-container *ngTemplateOutlet=\"graphViewButtons; context: { tile: graphTile }\"></ng-container>\n      </div>\n\n      <div class=\"tile-footer\">\n        <ng-container *ngTemplateOutlet=\"graphNameWithStatus; context: { tile: graphTile }\"></ng-container>\n        <!-- Graph editing in progress by a specific user - info texts -->\n        <ng-container *ngIf=\"!graphTile.isGraphAvailableForEdit; else editorInfoLive\">\n          <ng-container *ngTemplateOutlet=\"graphEditorDetails; context: { tile: graphTile }\"></ng-container>\n        </ng-container>\n        <!-- Graph modification date + user text -->\n        <ng-template #editorInfoLive>\n          <!-- TODO: Change provided date format in backend to include time-->\n          <div class=\"tile-date-wrapper\">\n            <div class=\"tile-date-column\">\n              <div class=\"graph-editor-info _graph-modified-info\">Modified: {{ graphTile.lastModifiedDate }} <br> - {{ graphTile.lastModifiedBy }}</div>\n            </div>\n            <div class=\"tile-date-column\">\n              <div class=\"graph-editor-info _graph-deployed-info\">Deployed: {{ graphTile.lastDeployedDate }}</div>\n            </div>\n          </div>\n        </ng-template>\n      </div>\n    </ng-container>\n\n    <!-- Draft Graph Tile -->\n    <ng-template #draftTile>\n      <div class=\"fb-tile-badge-wrapper draft-badge-wrapper\">\n        <ng-container *ngTemplateOutlet=\"tileBadgeTemplate; context: { tile: graphTile }\"></ng-container>\n      </div>\n      <div class=\"tile-image-wrapper\">\n        <img *ngIf=\"graphTile.image\" [src]=\"graphTile.image\" class=\"tile-image-small _tile-image-small\">\n      </div>\n      <div class=\"hover-button-items-row\">\n        <ng-container *ngTemplateOutlet=\"graphViewButtons; context: { tile: graphTile }\"></ng-container>\n      </div>\n      <div class=\"tile-footer\">\n        <ng-container *ngIf=\"hasScheduledJobs; else standardGraphText\">\n          <ng-container *ngTemplateOutlet=\"graphNameWithStatus; context: { tile: graphTile }\"></ng-container>\n        </ng-container>\n        <ng-template #standardGraphText>\n          <div class=\"graph-name truncate-with-ellipsis-wrap-2 _graph-name\" [title]=\"graphTile.name || ''\">\n            {{ graphTile.name || '' }}\n          </div>\n        </ng-template>\n        <!-- Graph editing in progress by a specific user - info texts -->\n        <ng-container *ngIf=\"!graphTile.isGraphAvailableForEdit; else editorInfo\">\n          <ng-container *ngTemplateOutlet=\"graphEditorDetails; context: { tile: graphTile }\"></ng-container>\n        </ng-container>\n        <ng-template #editorInfo>\n          <!-- TODO: Change provided date format in backend to include time-->\n          <div class=\"graph-editor-info _graph-modified-info\">Modified: {{ graphTile.lastModifiedDate }} <br> - {{ graphTile.lastModifiedBy }}</div>\n        </ng-template>\n      </div>\n    </ng-template>\n  </div>\n\n  <!-- Graph Controls (deploy, edit, copy, delete, export) -->\n  <div class=\"graph-tile-controls-column\">\n    <div\n      *ngIf=\"!graphTile.isLive\"\n      class=\"graph-tile-icon graph-tile-icon-deploy _graph-tile-icon-deploy\"\n      (click)=\"[tileActionHandler('deploy', graphTile), stopClickPropagation($event)]\">\n      <span class=\"icon-hover-tooltip\">Go Live</span>\n    </div>\n    <div\n      class=\"graph-tile-icon graph-tile-icon-copy _graph-tile-icon-copy\"\n      (click)=\"[tileActionHandler('copy', graphTile), stopClickPropagation($event)]\">\n      <span class=\"icon-hover-tooltip\">Copy</span>\n    </div>\n    <div\n      *ngIf=\"!graphTile.isLive && !hasScheduledJobs\"\n      class=\"graph-tile-icon graph-tile-icon-delete _graph-tile-icon-delete\"\n      (click)=\"[tileActionHandler('delete', graphTile), stopClickPropagation($event)]\">\n      <span class=\"icon-hover-tooltip\">Delete</span>\n    </div>\n    <div\n      class=\"graph-tile-icon graph-tile-icon-export _graph-tile-icon-export\"\n      (click)=\"[tileActionHandler('export', graphTile), stopClickPropagation($event)]\">\n      <span class=\"icon-hover-tooltip\">Export</span>\n    </div>\n  </div>\n\n</div>\n\n<!-- Common Templates -->\n<!-- Graph tile buttons (view / edit) -->\n<ng-template #graphViewButtons let-tile=\"tile\">\n  <span\n    id=\"ld-read-graph\"\n    class=\"graph-tile-button ld-secondary-small-button _graph-tile-view-only-button\"\n    (click)=\"[tileActionHandler('read', tile), stopClickPropagation($event)]\"\n  >\n    View/Comment\n  </span>\n  <span\n    id=\"ld-edit-graph\"\n    class=\"graph-tile-button ld-primary-small-button _graph-tile-edit-button\"\n    [ngClass]=\"{ 'disabled': !tile.isGraphAvailableForEdit && !tile.canGraphBeOveridden }\"\n    (click)=\"[tileActionHandler('edit', tile), stopClickPropagation($event)]\"\n  >\n    Edit\n  </span>\n</ng-template>\n\n<!-- Graph name with validation status -->\n<ng-template #graphNameWithStatus let-tile=\"tile\">\n  <div class=\"graph-name-wrapper\">\n    <!-- Invalid icon -->\n    <div *ngIf=\"!tile.isValid && !tile.isValidatingAsync\" class=\"graph-tile-error-icon validation-error-icon validation-error-icon-xtra-small _graph-error-icon\"></div>\n    <!-- Validation in progress spinner -->\n    <p-progressSpinner\n      *ngIf=\"tile.isValidatingAsync\"\n      [style]=\"{width:'12px',height:'12px','margin-right':'5px'}\" \n      strokeWidth=\"8\" \n      animationDuration=\"0.5s\"\n      class=\"_graph-validation-spinner\">\n    </p-progressSpinner>\n    <!-- Graph name -->\n    <span class=\"graph-name truncate-with-ellipsis-wrap-2 _graph-name \" [title]=\"tile.name || ''\" [ngClass]=\"{ 'invalid-graph': !tile.isValid }\">{{ tile.name || '' }}</span>\n  </div>\n</ng-template>\n\n<!-- Graph editor details -->\n<ng-template #graphEditorDetails let-tile=\"tile\">\n  <div class=\"graph-editor-name _graph-editor-name\">{{ tile.editedByName }}</div>\n  <div class=\"graph-editor-message _graph-editor-message\">is editing the graph.</div>\n</ng-template>\n\n<!-- Scheduled Jobs table popup -->\n<ng-template #tileBadgeTemplate let-tile=\"tile\">\n  <div\n    *ngIf=\"tile.scheduledJobs?.length > 0\"\n    [class.scheduled-modal-open]=\"scheduledJobsModal?.visible\"\n    class=\"scheduled-text-badge\"\n    (click)=\"[scheduledJobsModal.toggleModal(), tileActionHandler('scheduledJobsToggle', tile), stopClickPropagation($event)]\">\n    SCHEDULED ({{ tile.scheduledJobs.length }})\n  </div>\n  <ld-scheduled-jobs-modal\n    #scheduledJobsModal\n    [data]=\"tile.scheduledJobs\"\n    [isGraphView]=\"false\"\n    position=\"left\"\n  >\n  </ld-scheduled-jobs-modal>\n</ng-template>\n");

