/* harmony default export */ __webpack_exports__["default"] = ("<!-- Header section for node -->\n<div class=\"additional-header-text-section assign-owner-header-section\">\n  <div *ngIf=\"nodeEditorCtrl.sObjectType !== 'Meeting'\" class=\"node-section-text\">\n    Assign a record to a specific owner (from your list of Users and Queues) or a user from a Variable field.\n    <div class=\"italic\">\n      Note: This node only supports editable User fields.\n    </div>\n  </div>\n</div>\n\n<!-- Node name + collapsible description section (Required for all nodes)-->\n<ld-node-name-description></ld-node-name-description>\n\n<!-- Main node properties content -->\n<div *ngIf=\"nodeEditorCtrl.sObjectType !== 'Meeting'\" class=\"node-editor-section variable-setter-section\">\n  <ld-variable-setter\n    #variableSetter\n    placeholder=\"Enter or Select a Variable\"\n    bodyIndent=\"11\"\n    [context]=\"nodeEditorCtrl.nodeInfo\"\n    [disabled]=\"nodeEditorCtrl.isReadOnly\"\n    [needsUpgrade]=\"!this.fpService.isFeatureEnabled('NODE:RELATED_RECORDS_UPDATE')\"\n    [nodeNamesToNodesMap]=\"nodeEditorCtrl.nodeNamesToNodesMap\"\n    [variablesHandler]=\"nodeEditorCtrl.variablesHandler\"\n    [sObjectType]=\"nodeEditorCtrl.sObjectType\"\n    [variableKey]=\"variableKey\"\n    [showAllVariables]=\"true\"\n    [header]=\"variableSetterDescription.header\"\n    [body]=\"variableSetterDescription.body\"\n    [confirmOnObjectTypeChange]=\"true\"\n    (onSelect)=\"onVariableSelection($event)\"\n    bottomBorderClass=\"bottom-border-lt-grey-1\"\n    inputMode=\"read\"\n  ></ld-variable-setter>\n  <div class=\"node-section-text user-field-text\">Which {{ getObjectTypeLabel(variableObjectType) }} User field do you want to update?</div>\n  <div style=\"display:flex; margin-left: 15px; padding-bottom:10px;\" *ngIf=\"fieldAssignmentTypeaheadOptions\">\n    <ld-typeahead\n      #fieldAssignmentTypeahead\n      class=\"specific-owner-selector\"\n      placeholder=\"Search\"\n      [data]=\"fieldAssignmentTypeaheadOptions.data\"\n      nestingRoot=\"userFields\"\n      [required]=\"true\"\n      [requireSelectionFromData]=\"true\"\n      [disableBreadcrumbs]=\"true\"\n      [filter]=\"fieldAssignmentTypeaheadOptions.filter\"\n      [selections]=\"fieldAssignmentTypeaheadOptions.selection\"\n      (onSelect)=\"fieldAssignmentTypeaheadOptions.onSelect($event)\"\n      [style.width.px]=\"300\"\n      [disabled]=\"nodeEditorCtrl.isReadOnly\"\n    ></ld-typeahead>\n  </div>\n  <div *ngIf=\"variableObjectType === 'Contact' || variableObjectType === 'Opportunity'\" [style.margin-left.px]=\"15\">\n    <hr class=\"horizontal-line-separator-lt-grey-1\">\n    <div  [style.margin-bottom.px]=\"20\" [style.margin-top.px]=\"15\">\n      <p-checkbox\n        [(ngModel)]=\"nodeEditorCtrl.nodeInfo.updateAccountOwner\"\n        styleClass=\"ng-checkbox-small\"\n        [label]=\"'Update the ' + variableObjectType + '’s Account Owner'\"\n        binary=\"true\"\n      ></p-checkbox>\n    </div>\n  </div>\n</div>\n<!-- Rules -->\n<div class=\"node-editor-section ownership-section\" style=\"padding-left: 10px;\">\n  <div *ngIf=\"nodeEditorCtrl.sObjectType !== 'Meeting'\">Who do you want to assign the {{ getObjectTypeLabel(variableObjectType) }} to?</div>\n  <div *ngIf=\"nodeEditorCtrl.sObjectType === 'Meeting'\" class=\"header-font\">Choose Main Meeting Host:</div>\n  <div class=\"control-group assignment-type-radio-control horizontal-tabbing-option-div\">\n    <p-radioButton \n      [(ngModel)]=\"nodeEditorCtrl.nodeInfo.assignmentType\"\n      label=\"Specific User\"\n      name=\"trigger-node-filter-radio-group\"\n      value=\"by user id\"\n      inputId=\"by user id\"\n      [disabled]=\"nodeEditorCtrl.isReadOnly\"\n    ></p-radioButton>\n    <div \n      *ngIf=\"nodeEditorCtrl.nodeInfo.assignmentType === 'by user id'\"\n      [class.radio-button-user-option]=\"nodeEditorCtrl.sObjectType\">\n      <div class=\"label-dropdown-container\" [style.margin-bottom.px]=\"8\">\n        <ld-typeahead\n          #specificOwnerSelector\n          class=\"specific-owner-selector\"\n          placeholder=\"Find and Select User\"\n          [required]=\"true\"\n          [requireSelectionFromData]=\"true\"\n          [disableBreadcrumbs]=\"true\"\n          [searchFunction]=\"userAsyncTypeaheadOptions.searchFunction\"\n          [filter]=\"userAsyncTypeaheadOptions.filter\"\n          [validationFunction]=\"userAsyncTypeaheadOptions.customValidationFunction\"\n          [selections]=\"userSelection\"\n          (onSelect)=\"userAsyncTypeaheadOptions.onSelect($event)\"\n          [style.width.px]=\"310\"\n          [disabled]=\"nodeEditorCtrl.isReadOnly\"\n        ></ld-typeahead>\n      </div>\n      <div class=\"label-dropdown-container\" [style.margin-bottom.px]=\"12\">\n        Selected User:\n        <div \n            *ngIf=\"userSelection && userSelection.length > 0 && !showInvalidOrInactiveText && !showInvalidNoAssignText\"\n            class=\"selected-user-information-text\"\n            >\n          <a *ngIf=\"nodeEditorCtrl.nodeInfo['explicit owner assignment id'] !== 'None'\" [href]=\"'/' + userSelection[0].Id\" target=\"_blank\">{{userSelection[0].name}} ({{userSelection[0].Id}})</a>\n          <div *ngIf=\"nodeEditorCtrl.nodeInfo['explicit owner assignment id'] === 'None'\">{{userSelection[0].name}} ({{userSelection[0].Id}})</div>\n        </div>\n        <div *ngIf=\"nodeEditorCtrl.nodeInfo['explicit owner assignment id'] !== 'None' && showInvalidOrInactiveText\" class=\"selected-user-information-text\">\n          <a class=\"error-message\" [href]=\"'/' + nodeEditorCtrl.nodeInfo['explicit owner assignment id']\" target=\"_blank\">Owner Id {{nodeEditorCtrl.nodeInfo['explicit owner assignment id']}} does not exist or is inactive.</a>\n        </div>\n        <div \n            *ngIf=\"!nodeEditorCtrl.nodeInfo['explicit owner assignment id'] && !showInvalidOrInactiveText && !showInvalidNoAssignText\"\n            class=\"selected-user-information-text\"\n            >\n          None\n        </div>\n        <div *ngIf=\"showInvalidNoAssignText\" class=\"selected-user-information-text error-message\">Can only select \"< No Assignee >\" for Custom Fields</div>\n      </div>\n    </div>\n    <p-radioButton \n      [(ngModel)]=\"nodeEditorCtrl.nodeInfo.assignmentType\"\n      label=\"User from Variable Field\"\n      name=\"trigger-node-filter-radio-group\"\n      value=\"user field\"\n      inputId=\"user field\"\n      [disabled]=\"nodeEditorCtrl.isReadOnly\"\n    ></p-radioButton>\n    <div \n      *ngIf=\"nodeEditorCtrl.nodeInfo.assignmentType === 'user field'\" \n      class=\"radio-button-user-option\"\n      [style.margin-bottom.px]=\"5\">\n      <div class=\"col\" style=\"width: 50%;\">\n        <ld-typeahead\n          #customUserFieldSelector\n          class=\"custom-user-field-selector\"\n          placeholder=\"Search\"\n          customNestingRootLabel=\"Variables\"\n          [nestingRoot]=\"customUserFieldDropdownOptions.root\"\n          [getDynamicData]=\"customUserFieldDropdownOptions.getDynamicData\"\n          [filter]=\"customUserFieldDropdownOptions.filter\"\n          [postRefreshMetaData]=\"customUserFieldDropdownOptions.postRefreshMetaData\"\n          [refreshMetaData]=\"customUserFieldDropdownOptions.refreshMetaData\"\n          [required]=\"true\"\n          [requireSelectionFromData]=\"true\"\n          [selections]=\"customUserFieldDropdownOptions.selection\"\n          [validationFunction]=\"customUserFieldDropdownOptions.customValidationFunction\"\n          (onSelect)=\"customUserFieldDropdownOptions.onSelect($event)\"\n          [disabled]=\"nodeEditorCtrl.isReadOnly\"\n        ></ld-typeahead>\n      </div>\n    </div>\n  </div>\n</div>\n<hr class=\"horizontal-line-separator\">\n<div *ngIf=\"nodeEditorCtrl.sObjectType !== 'Meeting'\">\n  <div\n      #respectSchedule \n      id=\"respect-schedules-wrapper\"\n      [style.margin-top.px]=\"14\"\n      [style.margin-bottom.px]=\"nodeEditorCtrl.nodeInfo.hasOwnProperty('respectSchedules') ? 13 : 20\"\n  ></div>\n  <hr class=\"horizontal-line-separator\">\n  <div #emailNotification id=\"email-notification-wrapper\" [style.margin-top.px]=\"14\"></div>\n</div>\n<div *ngIf=\"nodeEditorCtrl.sObjectType === 'Meeting'\">\n  <div #schedulingSection id=\"scheduling-container\" class=\"backbone-component\"></div>\n</div>\n<hr class=\"horizontal-line-separator\">\n<ld-advanced-settings-edge-menu\n    descriptionText=\"Specify the target node, if any, when a condition below is met.\"\n></ld-advanced-settings-edge-menu>\n");

