/* harmony default export */ __webpack_exports__["default"] = ("<div id=\"comment\">\n  <!-- Header -->\n  <div *ngIf=\"!nodeEditorCtrl.isRoutingInsightsView && !nodeEditorCtrl.nodeInfo.editor\" class=\"comment-header\">Create a Comment</div>\n  <div *ngIf=\"!nodeEditorCtrl.isRoutingInsightsView && nodeEditorCtrl.nodeInfo.editor\" class=\"comment-header\">Edit a Comment</div>\n  <div *ngIf=\"nodeEditorCtrl.isRoutingInsightsView\" class=\"comment-header\">View a Comment</div>\n\n  <div class=\"comment-note\">Comments are viewable by all users with Routing Insights access.</div>\n\n  <!-- Comment Section -->\n  <div class=\"title-wrapper\">\n    <div class=\"section-title comment-title\">Comment</div>\n    <!-- TODO: Comment -->\n    <div class=\"comment-info\">\n      <div *ngIf=\"nodeEditorCtrl.nodeInfo.editor && nodeEditorCtrl.nodeInfo.dateTime.getTime() !== nodeEditorCtrl.nodeInfo.createdDateTime.getTime()\" class=\"info-item last-modified\">\n        Last Modified: {{ nodeEditorCtrl.nodeInfo.editor }} / \n        <span\n          class=\"date-time ld-body-small\"\n          [innerHTML]=\"(nodeEditorCtrl.nodeInfo.dateTime | dateTime: 'MM-DD-YYYY hh:mmA z') + timeZone\"\n        ></span>\n      </div>\n      <div *ngIf=\"nodeEditorCtrl.nodeInfo.createdDateTime !== 'Comment not saved'\" class=\"info-item created-by\">\n        Created: {{ nodeEditorCtrl.nodeInfo.author }} / \n        <span\n          class=\"date-time ld-body-small\"\n          [innerHTML]=\"(nodeEditorCtrl.nodeInfo.createdDateTime | dateTime: 'MM-DD-YYYY hh:mmA z') + timeZone\"\n        ></span>\n      </div>\n    </div>\n  </div>\n  <div class=\"comment-text-section\">\n    <textarea \n      #commentTextArea\n      class=\"ld-textarea-large vertical-resize-only comment-textarea\"\n      [value]=\"commentService.textAreaContent\"\n      placeholder=\"Add a comment about one or multiple nodes. Comments can capture key decision points or summaries of processes in the graph.\"\n      (input)=\"handleInputChange($event.target.value)\"\n      [disabled]=\"nodeEditorCtrl.isRoutingInsightsView || null\"\n    >{{ commentService.textAreaContent }}</textarea>\n    <div *ngIf=\"maxLimitReachedErrorMessage\" class=\"comment-error-message error-message\">{{ maxLimitReachedErrorMessage }}</div>\n  \n  </div>\n  \n  <!-- Tag Nodes Section -->\n  <div class=\"title-wrapper\">\n    <div class=\"section-title tag-nodes-title\">Tag Nodes</div>\n    <ld-tooltip [content]=\"calloutTooltipContent\" size=\"medium\"></ld-tooltip>\n  </div>\n  <div class=\"optional-hint\">optional</div>\n\n  <p-multiSelect\n    [(ngModel)]=\"commentService.taggedNodes\"\n    (ngModelChange)=\"onTaggedNodesChange()\"\n    [options]=\"nodesCollection\"\n    [disabled]=\"nodeEditorCtrl.isRoutingInsightsView\"\n    styleClass=\"ng-multiselect-dropdown-large search-enabled comment-nodes-multiselect\"\n    dropdownIcon=\"down-arrow-icon\"\n    optionLabel=\"label\"\n    defaultLabel=\"Select a node\"\n    maxSelectedLabels=\"0\"\n    [filter]=\"true\"\n    [resetFilterOnHide]=\"true\"\n    [selectedItemsLabel]=\"commentService.taggedNodes.length === nodesCollection.length ? 'All nodes selected' : (commentService.taggedNodes.length === 1 ? '1 node selected' : '{0} nodes selected')\"\n    scrollHeight=\"350px\"\n  ></p-multiSelect>\n\n  <!-- Chip -->\n  <div *ngIf=\"commentService.taggedNodes.length\" class=\"chip-row-wrapper\">\n    <ld-chip\n      *ngFor=\"let node of commentService.taggedNodes; let i = index\"\n      class=\"tag-nodes-chip\"\n      [label]=\"node.label\"\n      [closable]=\"!nodeEditorCtrl.isRoutingInsightsView\"\n      (remove)=\"removeChip(i)\"\n    ></ld-chip>\n  </div>\n</div>\n");

