/* harmony default export */ __webpack_exports__["default"] = ("<ld-node-name-description></ld-node-name-description>\n\n<div class=\"related-object-section\">\n  <p-accordion\n    class=\"get-records\"\n    styleClass=\"collapsible-content\"\n    expandIcon=\"right-arrow-icon small-arrow-props\"\n    collapseIcon=\"down-arrow-icon small-arrow-props\"\n    [multiple]=\"true\"\n    (onOpen)=\"onOpenAccordionHandler($event)\"\n  >\n    <p-accordionTab\n      [transitionOptions]=\"'0ms'\"\n      class=\"ui-accordion-bold\"\n      [(selected)]=\"accordionStates[0].opened\"\n    >\n      <p-header>\n        <span>\n          <strong>Step 1:</strong> Search Criteria\n          <div\n            class=\"validation-error-icon validation-error-icon-xtra-small inline-block\"\n            *ngIf=\"!this.accordionStates[0].valid\"\n          ></div>\n        </span>\n      </p-header>\n      <div [style.margin-top.px]=\"17\">\n        <div class=\"node-section-header-text\" [style.margin-bottom.px]=\"7\">\n          What object are you looking for?\n        </div>\n        <div [style.width.px]=\"300\" [style.margin-bottom.px]=\"10\">\n          <ld-typeahead\n            placeholder=\"Find and Select Object\"\n            [data]=\"possibleFirstObjects\"\n            [selections]=\"firstObjectSelection\"\n            (onSelect)=\"handleFirstSelect($event)\"\n            [disabled]=\"nodeEditorCtrl.isReadOnly\"\n            [selectOnEnter]=\"true\"\n            [required]=\"true\"\n            (onFocus)=\"clickInFirstDropdownHandler()\"\n            [delay]=\"0\"\n            [readOnly]=\"nodeEditorCtrl.isReadOnly\"\n          ></ld-typeahead>\n        </div>\n\n        <hr class=\"horizontal-line-separator-20\" />\n\n        <div class=\"node-section-header-text\" [style.margin-bottom.px]=\"10\">\n          How do you want to get records?\n        </div>\n        <div [style.margin-bottom.px]=\"20\">\n          <p-radioButton\n            label=\"Related List Search\"\n            value=\"related\"\n            [(ngModel)]=\"radioButtonFirst\"\n            [disabled]=\"firstObjectSelection.length === 0\"\n            [labelStyleClass]=\"firstObjectSelection.length === 0 ? 'disabled-radio-text' : ''\"\n          ></p-radioButton>\n          <div class=\"get-records-first-accordion-box\" *ngIf=\"radioButtonFirst === 'related'\">\n            <p\n              [class.disabled-radio-text]=\"firstObjectSelection.length === 0\"\n              [style.margin-bottom.px]=\"8\"\n              [innerHTML]=\"firstLabel() | safeHtml\"\n            ></p>\n            <div [style.width.px]=\"300\">\n              <ld-typeahead\n                #secondDropdown\n                placeholder=\"Select Parent Object\"\n                [nestingRoot]=\"'Object'\"\n                [filter]=\"secondDropdownFilter.bind(this)\"\n                [selections]=\"secondDropdownSelections\"\n                (onSelect)=\"handleSecondSelect($event)\"\n                [getDynamicData]=\"getDynamicData.bind(this)\"\n                (onFocus)=\"clickInSecondDropdownHandler()\"\n                (onClickOut)=\"clickOutSecondDropdownHandler()\"\n                [required]=\"true\"\n                [disabled]=\"nodeEditorCtrl.isReadOnly || relatedObjectName === ''\"\n                [delay]=\"0\"\n                [readOnly]=\"nodeEditorCtrl.isReadOnly\"\n              ></ld-typeahead>\n            </div>\n            <p\n              [style.margin-top.px]=\"18\"\n              [class.disabled-radio-text]=\"firstObjectSelection.length === 0\"\n              [style.margin-bottom.px]=\"8\"\n              [innerHTML]=\"secondLabel() | safeHtml\"\n            ></p>\n            <div [style.width.px]=\"300\">\n              <ld-typeahead\n                placeholder=\"Select Lookup Field\"\n                [data]=\"possibleFields\"\n                [selections]=\"thirdSelection\"\n                (onSelect)=\"handleThirdSelect($event)\"\n                [disabled]=\"nodeEditorCtrl.isReadOnly || possibleFields.length < 2\"\n                [readOnly]=\"nodeEditorCtrl.isReadOnly || !(possibleFields.length > 1 || secondDropdownSelections.length === 0)\"\n                [selectOnEnter]=\"true\"\n                [required]=\"true\"\n                [delay]=\"0\"\n              ></ld-typeahead>\n            </div>\n          </div>\n          <div class=\"search-text\" *ngIf=\"radioButtonFirst === 'related'\">\n            <p><strong class=\"search-label\">Search: </strong>\n              <span [innerHTML]=\"searchText() | safeHtml\"></span>\n            </p>\n          </div>\n          <p-radioButton\n            label=\"SOQL Search (Coming Soon!)\"\n            disabled=\"true\"\n            labelStyleClass=\"disabled-radio-text\"\n          ></p-radioButton>\n        </div>\n      </div>\n    </p-accordionTab>\n\n    <p-accordionTab\n      [transitionOptions]=\"'0ms'\"\n      class=\"ui-accordion-bold\"\n      [(selected)]=\"accordionStates[1].opened\"\n      [disabled]=\"!accordionStates[1].enabled\"\n    >\n      <p-header *ngIf=\"!accordionStates[1].enabled\" pTooltip=\"You must complete the previous step’s requirements\" tooltipPosition=\"top\">\n        <span>\n          <strong>Step 2:</strong> Filter Records\n          <div\n            class=\"validation-error-icon validation-error-icon-xtra-small inline-block\"\n            *ngIf=\"!this.accordionStates[1].valid\"\n          ></div>\n        </span>\n      </p-header>\n      <p-header *ngIf=\"accordionStates[1].enabled\">\n        <span>\n          <strong>Step 2:</strong> Filter Records\n          <div\n            class=\"validation-error-icon validation-error-icon-xtra-small inline-block\"\n            *ngIf=\"!this.accordionStates[1].valid\"\n          ></div>\n        </span>\n      </p-header>\n      <div class=\"related-object-section\" [style.margin-top.px]=\"14\">\n        <p [innerHTML]=\"thirdLabel() | safeHtml\"></p>\n        <div>\n          <ld-filter-rules\n            *ngIf=\"accordionStates[1].enabled\"\n            [radioButtonsList]=\"filterRulesOptions.radioButtonsList\"\n            [ruleHeader]=\"filterRulesOptions.ruleHeader\"\n            [ruleSubHeader]=\"filterRulesOptions.ruleSubHeader\"\n            [selectedRadio]=\"selectedFilterRadio\"\n            (dataEmitter)=\"handleFilterRulesDataChange($event)\"\n            [disabled]=\"!accordionStates[1].enabled || nodeEditorCtrl.isReadOnly\"\n            [overrideLeftObjectType]=\"relatedObjectName\"\n            [overrideRightObjectType]=\"primarySObjectType\"\n            [nodeModel]=\"nodeEditorCtrl.nodeModel\"\n            [readOnly]=\"nodeEditorCtrl.isReadOnly\"\n          ></ld-filter-rules>\n        </div>\n      </div>\n    </p-accordionTab>\n\n    <p-accordionTab\n      [transitionOptions]=\"'0ms'\"\n      class=\"ui-accordion-bold\"\n      [(selected)]=\"accordionStates[2].opened\"\n      [disabled]=\"!accordionStates[2].enabled\"\n    >\n      <p-header *ngIf=\"!accordionStates[2].enabled\" pTooltip=\"You must complete the previous step’s requirements\" tooltipPosition=\"top\">\n        <span>\n          <strong>Step 3:</strong> Store Records\n          <div\n            class=\"validation-error-icon validation-error-icon-xtra-small inline-block\"\n            *ngIf=\"!this.accordionStates[2].valid\"\n          ></div>\n        </span>\n      </p-header>\n      <p-header *ngIf=\"accordionStates[2].enabled\">\n        <span>\n          <strong>Step 3:</strong> Store Records\n          <div\n            class=\"validation-error-icon validation-error-icon-xtra-small inline-block\"\n            *ngIf=\"!this.accordionStates[2].valid\"\n          ></div>\n        </span>\n      </p-header>\n\n      <div class=\"node-section-header-text\" [style.margin-top.px]=\"16\" [style.margin-bottom.px]=\"9\">\n        How many {{ getObjectLabel(relatedObjectName, true) }} records to store?\n      </div>\n\n      <p-radioButton\n        label=\"One {{ getObjectLabel(relatedObjectName, false) }}\"\n        [(ngModel)]=\"radioButtonThird\"\n        value=\"one\"\n      ></p-radioButton>\n      <div\n        class=\"node-editor-section rules-section tiebreakers-box\"\n        [class.rules-disabled]=\"false\"\n        *ngIf=\"radioButtonThird === 'one'\"\n      >\n        <div class=\"node-section-text rules-description-text\">\n          Identify the ultimate related record to be selected when LeanData finds multiple matches.\n        </div>\n        <div #rulesESM id=\"criteria-list-partial\" class=\"rules-table-wrapper\"></div>\n      </div>\n\n      <p-radioButton\n        label=\"All Records (Coming Soon!)\"\n        disabled=\"true\"\n        labelStyleClass=\"disabled-radio-text\"\n      ></p-radioButton>\n\n      <hr class=\"horizontal-line-separator-10-wide\" />\n\n      <ld-variable-setter\n        #variableSetter\n        placeholder=\"Enter or Select a Variable\"\n        [context]=\"nodeEditorCtrl.nodeInfo\"\n        [nodeNamesToNodesMap]=\"nodeEditorCtrl.nodeNamesToNodesMap\"\n        [variablesHandler]=\"nodeEditorCtrl.variablesHandler\"\n        [sObjectType]=\"relatedObjectName\"\n        [disabled]=\"nodeEditorCtrl.isReadOnly\"\n        [topBorder]=\"false\"\n        [isROR]=\"true\"\n        [header]=\"variableSetterDescription.header\"\n        [body]=\"variableSetterDescription.body\"\n        variableKey=\"outputVariable\"\n      ></ld-variable-setter>\n    </p-accordionTab>\n  </p-accordion>\n</div>\n\n<hr class=\"horizontal-line-separator-10\" />\n\n<ld-advanced-settings-edge-menu\n  descriptionText=\"Specify the target node, if any, when a condition below is met.\"\n></ld-advanced-settings-edge-menu>\n");

