/* harmony default export */ __webpack_exports__["default"] = ("<div id=\"matching-settings-wrapper\" class=\"angular-page-wrapper-props\">\n  <div class=\"ld-header\">Matching</div>\n  <div class=\"ld-subheader\">Matching Settings</div>\n  <div class=\"ld-header-description\">These settings determine how objects are selected and prioritized for matching throughout the product.</div>\n  <p-tabView styleClass=\"short-panels\">\n    <p-tabPanel>\n      <ng-template pTemplate=\"header\">General</ng-template>\n      <div class=\"section-container\">\n        <div class=\"domain-only-header\">\n          <span class=\"ld-section-header\">Domain Only Matching for Tagging and Routing</span>\n          <span class=\"ld-body-large\">\n            By default, LeanData utilizes domain matches along with other standard criteria to determine a match.<br>\n            When enabled, this setting will include records for tiebreaking even if the <b>only</b> matching criteria is the domain name.<br>\n            <i><b>Warning:</b> This may pull in low-quality match results.</i>\n          </span>\n        </div>\n        <div class=\"domain-only-setting\">\n          <div class=\"allow-domain-checkbox\">\n            <p-checkbox\n              [(ngModel)]=\"allowDomainOnlyMatchingOn\"\n              (onChange)=\"handleDomainOnlyChange($event)\"\n              [style]=\"{ 'margin-left': '10px' }\"\n              styleClass=\"ng-checkbox-large\"\n              label=\"Allow Domain Only Matching for Tagging and Routing\"\n              binary=\"true\"\n              class=\"_allow-domain-checkbox\"\n            >\n            </p-checkbox>\n          </div>\n          <div class=\"allow-domain-radios\">\n            <p-radioButton\n              [(ngModel)]=\"selectedDomainMatchingRadio\"\n              value=\"fallbackON\"\n              (onClick)=\"handleAllowDomainRadioClick()\"\n              label=\"Use as Fallback (Only include if no other matches are found)\"\n              [disabled]=\"!allowDomainOnlyMatchingOn\"\n              class=\"_use-as-fallback-radiobutton\">\n            </p-radioButton>\n            <p-radioButton\n              [(ngModel)]=\"selectedDomainMatchingRadio\"\n              value=\"alwaysON\"\n              (onClick)=\"handleAllowDomainRadioClick()\"\n              label=\"Always Include\"\n              [disabled]=\"!allowDomainOnlyMatchingOn\"\n              class=\"_always-include-radiobutton\">\n            </p-radioButton>\n          </div>\n        </div>\n      </div>\n      <div class=\"section-container routing-match-limits\">\n        <div class=\"match-limits-header\">\n          <span class=\"ld-section-header\">Routing Match Limits</span>\n          <span class=\"ld-body-large\">\n            Specify the number of matched records to return in LeanData Routing.<br>\n            <i><b>Recommended:</b></i> Set each limit to 1,000 or fewer matched records to improve overall system performance.\n          </span>\n        </div>\n        <div class=\"match-limits-settings ld-body-large\">\n          <div *ngFor=\"let setting of matchSettings | keyvalue:originalOrder; let idx = index\">\n            <div class=\"match-limits-setting-row\">\n              <div class=\"match-limits-setting-header\">\n                <span><b>Matched {{ getPluralObjectName(setting.key) }}</b></span>\n              </div>\n              <div class=\"match-limits-setting-return-text\">\n                <span>Return the first</span>\n              </div>\n              <div class=\"match-limits-setting-num-input\">\n                <input\n                  type=\"number\"\n                  pInputText\n                  [(ngModel)]=\"setting.value.limit\"\n                  (change)=\"handleMatchLimitInputChange(setting.key, $event)\"\n                  class=\"ld-input-large hide-input _match-limit-input-{{ setting.key }}\"\n                />\n              </div>\n              <div class=\"match-limits-setting-matched-text\">\n                <span>matched {{ getPluralObjectName(setting.key) }} sorted by</span>\n              </div>\n              <div class=\"match-limits-setting-sortedby-dropdown\">\n                <p-dropdown\n                  [options]=\"sortedOptionsByObj[setting.key]\"\n                  [(ngModel)]=\"selectedOptionByObj[setting.key]\"\n                  (onChange)=\"handleSortDropdownChange(setting.key, $event)\"\n                  styleClass=\"ng-dropdown-large\"\n                  dropdownIcon=\"down-arrow-icon\"\n                  class=\"_match-limit-sorted-option-{{ setting.key }}\">\n                </p-dropdown>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </p-tabPanel>\n    <p-tabPanel *ngIf=\"isFeatureEnabled\">\n      <ng-template pTemplate=\"header\">Matching Fields\n        <div *ngIf=\"!allTabsValid\" class=\"dot-indicator\" pTooltip=\"Error: Missing or invalid field mappings detected. Please check and correct all fields before saving.\" tooltipPosition=\"right\"></div>\n      </ng-template>\n      <p-tabView styleClass=\"tab-view-small\" >\n        <p-tabPanel *ngFor=\"let sObjectType of matchingSettingsService.supportedObjectTypes\">\n          <ng-template pTemplate=\"header\">\n            {{ sObjectType }}\n            <div *ngIf=\"!matchingSettingsService.tabValidStates[sObjectType]\" class=\"dot-indicator\" pTooltip=\"Error: Missing or invalid field mappings detected. Please check and correct all fields before saving.\" tooltipPosition=\"right\"></div>\n          </ng-template>\n          <ld-field-matching-settings\n            [sObjectType]=\"sObjectType\"\n            [showSpecialFieldMatching]=\"matchingSettingsService.specialFieldObjectTypes.has(sObjectType)\"\n            [matchingFieldMapping]=\"matchingFieldMappings[sObjectType]\"\n            [dropdownOptions]=\"myDropdownOptions[sObjectType]\"\n            [bodyText]=\"bodyTexts[sObjectType]\"\n          ></ld-field-matching-settings>\n        </p-tabPanel>\n      </p-tabView>\n    </p-tabPanel>\n  </p-tabView>\n</div>\n");

