/* harmony default export */ __webpack_exports__["default"] = ("<div id=\"round-robin-metrics-wrapper\" class=\"angular-page-wrapper-props ld-body-medium\">\n  <div class=\"beta-banner\">Round Robin Pool Metrics - BETA</div>\n  <header class=\"ui-g ui-fluid\">\n    <div class=\"ui-g-6\" style=\"padding-left:0;\">\n<!--      <div class=\"ld-header\">Round Robin Pool Metrics</div>-->\n      <h4 style=\"margin-top: 10px; display: block;\" class=\"_round-robin-pool-name\">\n        Round Robin Pool: <a target=\"_blank\" href=\"#routing/round_robin_pools/creator/{{ poolInfo.Id }}\"><strong class=\"pool-name-link\">{{ poolInfo.Grouping_Name__c }}</strong>&nbsp;<i class=\"pi pi-external-link\"></i></a>\n      </h4>\n    </div>\n    <div class=\"ui-g-6\" style=\"text-align: right;\">\n      <div class=\"dateFilterColumn\">\n        <label>Start Date</label>\n        <p-calendar [(ngModel)]=\"startDateFilter\" [disabled]=\"loading\" [maxDate]=\"currentDate\" [showIcon]=\"true\" ngClass=\"_start-date-filter\"></p-calendar>\n      </div>\n      <div class=\"dateFilterColumn\">\n        <label>End Date</label>\n        <p-calendar [(ngModel)]=\"endDateFilter\" [disabled]=\"loading\" [minDate]=\"startDateFilter\" [maxDate]=\"currentDate\" [showIcon]=\"true\" ngClass=\"_end-date-filter\"></p-calendar>\n      </div>\n      <div class=\"applyButtonColumn\">\n        <button type=\"button\" class=\"btn-apply-filters ld-primary-small-button\" (click)=\"applyFilters()\"><i class=\"pi pi-filter\"></i> Apply</button>\n      </div>\n      <div class=\"error-message\" style=\"text-align: right; margin-left: 10px;\" *ngIf=\"dateFilterValidationMessage\">{{ dateFilterValidationMessage }}</div>\n    </div>\n  </header> \n  \n  <hr class=\"horizontal-line-separator\" />\n\n  <p-tabView #tabView class=\"_tab-view-container\">\n    <p-tabPanel header=\"Distribution Metrics\" [selected]=\"true\" class=\"_distribution-metrics-tab\">\n      <div *ngIf=\"!loading\">\n        <p-table [value]=\"sortedPoolMembers\">\n          <ng-template pTemplate=\"header\">\n            <tr>\n              <th>Name</th>\n              <th>Date Added To Pool</th>\n              <th>Current Weight Value <a href=\"javascript:void(0);\" pTooltip=\"Member's weight value in the current pool's configuration\" style=\"vertical-align: middle;\"><i class=\"pi pi-info-circle\"></i></a></th>\n              <th>Routed <a href=\"\" pTooltip=\"Number of records routed in the specified timeframe. Percentage may not seem evenly distributed due to changes to the pool configuration and members' availability\" style=\"vertical-align: middle;\"><i class=\"pi pi-info-circle\"></i></a></th>\n              <th>Missed Routing <a href=\"\" pTooltip=\"Number of records routed to other members of the pool during the time this member was unavailable\" style=\"vertical-align: middle;\"><i class=\"pi pi-info-circle\"></i></a></th>\n              <th>Vacation Time (In Minutes)</th>\n            </tr>\n          </ng-template>\n          <ng-template pTemplate=\"body\" let-member>\n            <tr>\n              <td>{{member[\"Name\"]}}</td>\n              <td>{{member[\"AddedDate\"]}}</td>\n              <td><span *ngIf=\"member['WeightValue'] >= 0; then showWeightValue else showNA\"></span>\n                <ng-template #showWeightValue>{{member[\"WeightValue\"]}} ({{ ((member[\"WeightValue\"] / poolInfo[\"total weight value\"]) * 100).toFixed(1) }}%)</ng-template>\n                <ng-template #showNA>N/A <i class=\"pi pi-info-circle\" pTooltip=\"No data. Member no longer part of the pool\"></i></ng-template>\n              </td>\n              <td>{{member[\"Metrics\"][\"Routed\"]}} ({{member[\"Metrics\"][\"Routed %\"]}}%)</td>\n              <td>{{member[\"Metrics\"][\"Missed\"]}}</td>\n              <td>{{member[\"Metrics\"][\"VacationMinutes\"]}}</td>\n            </tr>\n          </ng-template>\n        </p-table>\n\n        <br />\n        <hr class=\"horizontal-line-separator\" />\n        <br />\n        \n        <p-chart #dailyVolumeLineChart type=\"line\" [data]=\"dailyVolumeMetricsLineChartDataset\" [options]=\"dailyVolumeMetricsLineChartDataset.options\"></p-chart>\n        \n        <br />\n        <hr class=\"horizontal-line-separator\" />\n        <br />\n\n        <p-chart #distributionPiechart type=\"pie\" [data]=\"distributionPiechartData\" [options]=\"distributionPiechartData.options\"></p-chart>\n\n        <br />\n        <hr class=\"horizontal-line-separator\" />\n        <br />\n\n        <p-chart type=\"bar\" [data]=\"missedLogsCountVsVacationTimeDataset\" [options]=\"missedLogsCountVsVacationTimeDataset.options\"></p-chart>\n\n        <br />\n        <hr class=\"horizontal-line-separator\" />\n        <br />\n\n        <p-chart type=\"bar\" [data]=\"missedLogsCountByUnavailabilityDataset\" [options]=\"missedLogsCountByUnavailabilityDataset.options\"></p-chart>\n      </div>\n      \n      <div style=\"text-align: center; width: 100%\" *ngIf=\"loading\">\n        <p-progressSpinner [style]=\"{width: '50px', height: '50px'}\" strokeWidth=\"8\" fill=\"#EEEEEE\" animationDuration=\".5s\"></p-progressSpinner>\n      </div>\n    </p-tabPanel>\n    <p-tabPanel header=\"Logs Report\" class=\"_logs-report-tab\">\n      <div *ngIf=\"tabNames[tabView.activeIndex] === 'report'\">\n        <ld-round-robin-simple-logs [pool-id]=\"poolId\" [metrics-page]=\"this\"></ld-round-robin-simple-logs>\n      </div>\n    </p-tabPanel>\n  </p-tabView>\n</div>\n");

