    reverseConditionLogic(filterLabel) {
        let operators = filterLabel.split(' ').filter(op => op.includes('OR') || op.includes('AND'));
        operators = operators.map((operator) => {
            let newOp = operator;
            if (operator.includes('OR'))
                newOp = `<span ${operator.replace('OR', 'AND')}</span>`;
            else if (operator.includes('AND'))
                newOp = `<span ${operator.replace('AND', 'OR')}</span>`;
            return newOp;
        });
        let conditions = filterLabel.split(/OR|AND/);
        conditions = conditions.map((condition) => {
            let newCond = condition;
            if (condition.includes('equals'))
                newCond = condition.replace(/equals/g, 'not equal to');
            else if (condition.includes('not equal'))
                newCond = condition.replace(/not equal to/g, 'equals');
            else if (condition.includes('starts'))
                newCond = condition.replace(/starts/g, 'does not start');
            else if (condition.includes('not start'))
                newCond = condition.replace(/does not start/g, 'starts');
            else if (condition.includes('ends'))
                newCond = condition.replace(/ends/g, 'does not end');
            else if (condition.includes('not end'))
                newCond = condition.replace(/does not end/g, 'ends');
            else if (condition.includes('contains'))
                newCond = condition.replace(/contains/g, 'does not contain');
            else if (condition.includes('not contain'))
                newCond = condition.replace(/does not contain/g, 'contains');
            else if (condition.includes('is null'))
                newCond = condition.replace(/is null/g, 'not null');
            else if (condition.includes('not null'))
                newCond = condition.replace(/not null/g, 'is null');
            else if (condition.includes('is public domain'))
                newCond = condition.replace(/is public domain/g, 'is not public domain');
            else if (condition.includes('is not public domain'))
                newCond = condition.replace(/is not public domain/g, 'is public domain');
            else if (condition.includes('domain fuzzy matches'))
                newCond = condition.replace(/domain fuzzy matches/g, 'domain does not fuzzy match');
            else if (condition.includes('domain does not fuzzy match'))
                newCond = condition.replace(/domain does not fuzzy match/g, 'domain fuzzy matches');
            else if (condition.includes('domain exact matches'))
                newCond = condition.replace(/domain exact matches/g, 'domain does not exact match');
            else if (condition.includes('domain does not exact match'))
                newCond = condition.replace(/domain does not exact match/g, 'domain exact matches');
            return newCond;
        });
        let reversedLabel = conditions[0];
        for (let i = 0; i < operators.length; i++) {
            reversedLabel += operators[i] += conditions[i + 1];
        }
        return reversedLabel;
    }
