    getFormFieldMappingInfo(parsedMessage, logNodeInfo, graphNodeInfo) {
        const fieldMapList = [];
        graphNodeInfo.fieldMapping.forEach((row) => {
            let field = row['form field'];
            let value = logNodeInfo['form field mapping attribs'][field] === undefined ? 'N/A' : logNodeInfo['form field mapping attribs'][field];
            if (field === 'logid') {
                field = 'LogID';
            }
            else if (field === 'owner') {
                field = 'OwnerID';
            }
            if (row['value field'].toLowerCase() === '{!logid}') {
                value = parsedMessage.logId;
            }
            ;
            fieldMapList.push({ value: `(${field}): ${value}` });
        });
        return {
            value: 'Form Field Mapping Info',
            excludeColon: true,
            idList: fieldMapList,
            headerBold: true,
        };
    }
    getScheduleNodeMoreInfoActionData(parsedMessage, logNodeInfo, graphNodeInfo) {
        const routingType = scheduleReference[graphNodeInfo.actionType];
        const moreInfoData = [];
        let fieldForReference;
        if (graphNodeInfo[routingType] === 'custom field') {
            fieldForReference = graphNodeInfo['custom field'];
        }
        else if (graphNodeInfo['assignmentType'] === 'user field') {
            fieldForReference = graphNodeInfo['user field'];
        }
        else if (graphNodeInfo['assignmentType'] === 'by user id') {
            fieldForReference = graphNodeInfo['assignmentType'];
        }
        else {
            fieldForReference = graphNodeInfo[routingType];
        }
        moreInfoData.push({
            label: 'Field Referenced for Scheduling',
            value: fieldForReference,
        });
        const referencedObject = this.getScheduleNodeReferencedObjectMoreInfo(parsedMessage, logNodeInfo, graphNodeInfo);
        moreInfoData.push(referencedObject);
        moreInfoData.push({
            label: 'Booked with',
            value: logNodeInfo['assignment field new'] || 'N/A',
        });
        if (logNodeInfo['additional attendees'] && logNodeInfo['additional attendees'].length > 0) {
            moreInfoData.push(this.getScheduleNodeAdditionalAttendeeMoreInfo(parsedMessage, logNodeInfo, graphNodeInfo));
        }
        moreInfoData.push({
            label: 'Meeting Type',
            value: graphNodeInfo['meeting type name'] ? graphNodeInfo['meeting type name'] : graphNodeInfo['meeting type id'],
        });
        if (logNodeInfo['form field mapping attribs']) {
            moreInfoData.push(this.getFormFieldMappingInfo(parsedMessage, logNodeInfo, graphNodeInfo));
        }
        ;
        if (logNodeInfo['event object'] && logNodeInfo['event object'].Id) {
            moreInfoData.push({
                label: 'New Event',
                value: logNodeInfo['event object'].Subject,
                link: `/${logNodeInfo['event object'].Id}`,
            });
            moreInfoData.push({
                value: 'More Info',
                idList: [
                    {
                        label: 'Event Type',
                        value: logNodeInfo['event object'].Type,
                    },
                    {
                        label: 'Owner Id',
                        value: logNodeInfo['event object'].OwnerId,
                    }
                ]
            });
        }
        else {
            moreInfoData.push({
                label: 'New Event',
            });
        }
        const unavailabilityStatusesMap = logNodeInfo['owner unavailability statuses'];
        if (unavailabilityStatusesMap) {
            const formattedIdList = [];
            for (const ownerId of Object.keys(unavailabilityStatusesMap)) {
                const ownerName = this.idToLabelMap[ownerId] + ' - ' + unavailabilityStatusesMap[ownerId].join(', ');
                if (ownerName.endsWith(' - Unauthorized User')) {
                    formattedIdList.push({
                        value: `<span class="error-message">
                      <a class="ld-link invalid-link" target="_blank" href="/${ownerId}">${ownerName}</a>
                    <span>`,
                        customHtml: true
                    });
                }
                else {
                    // other unavailability reasons
                    formattedIdList.push({
                        value: `<span><a target="_blank" href="/${ownerId}">${ownerName}</a><span>`,
                        customHtml: true
                    });
                }
            }
            moreInfoData.push({
                value: `Unavailable Pool Members (${formattedIdList.length})`,
                excludeColon: true,
                idList: formattedIdList,
            });
        }
        return moreInfoData;
    }
    getScheduleNodeAdditionalAttendeeMoreInfo(parsedMessage, logNodeInfo, graphNodeInfo) {
        const attendeeList = logNodeInfo['additional attendees'];
        const bookingInfo = this.getBookingInfoFromAttendeeList(attendeeList, false);
        const hasError = attendeeList.some((attendee) => {
            return !attendee.isValid || !attendee.isCalendarAuthorized;
        });
        return {
            value: `${attendeeList.length} other${attendeeList.length === 1 ? '' : 's'}`,
            excludeColon: true,
            idList: bookingInfo,
            showErrorIcon: hasError,
        };
    }
    getScheduleNodeReferencedObjectMoreInfo(parsedMessage, logNodeInfo, graphNodeInfo) {
        // default label and value
        const referencedObject = {
            label: scheduleMeetingType[graphNodeInfo.actionType],
            value: logNodeInfo[scheduleMeetingReferencedObject[graphNodeInfo.actionType]]
        };
        // If the action type has more than 1 possible place for value or the link is different,
        // Add to the switch statement below to replace the default value
        switch (graphNodeInfo.actionType) {
            case ACTION_TYPES.ASSIGN_OWNER:
                referencedObject['value'] = logNodeInfo['owner name'] || graphNodeInfo['explicit owner assignment id'];
                referencedObject['link'] = `/${graphNodeInfo['explicit owner assignment id']}`;
                break;
            case ACTION_TYPES.ROUND_ROBIN:
                referencedObject['link'] = `${this.ldUrlPrefix}#calendaring/round_robin_pools/creator/${logNodeInfo['roundRobinPoolId']}`;
                break;
            case ACTION_TYPES.ROUTE_TO_TERRITORY:
                referencedObject['link'] = logNodeInfo['segmentId'] ? `${this.ldUrlPrefix}#calendaring/territory_segments/assignments/${logNodeInfo['segmentId']}` : null;
        }
        return referencedObject;
    }
    /*Converting urlencodedformat to JSON helper function*/
    urlEncodeToJsonFormat(urlEncode) {
        /*
        let urlEncodeMap = new Map();
        urlEncodeMap.set('%40','@');
        */
        let jsonObj = {};
        let urlEncodeSplit = urlEncode.split("&");
        for (let i = 0; i < urlEncodeSplit.length; i++) {
            let argument = urlEncodeSplit[i].split("=");
            let param = argument[0];
            let value = argument[1];
            param = param.replace('%40', '@');
            value = value.replace('%40', '@');
            //wierd bug where even if k is set to %40, its not recognized as its string value, will look back later - davidshaw
            /*
            urlEncodeMap.forEach((k,v) => {
              if (param.includes(k)){
                param = param.replace(k,v);
              }
              if (value.includes(k)){
                console.log(value);
              }
            });
            */
            jsonObj[param] = value;
        }
        return jsonObj;
    }
