let FlowbuilderService = class FlowbuilderService {
    constructor() {
        this.hoverCardContent = '';
        this.cardClass = '';
        this.commentContent = '';
    }
    showCommentCard(commentContent, x, y) {
        this.updateCardPosition(x, y, 'comment');
        this.commentContent = commentContent;
    }
    hideCommentCard() {
        this.commentPosition = null;
    }
    showHoverCard(hoverContent, isGraphNode, x, y) {
        this.cardClass = isGraphNode ? 'node-name' : 'comment-text';
        this.updateCardPosition(x, y, 'hover');
        this.hoverCardContent = hoverContent;
    }
    hideHoverCard() {
        this.hoverCardPosition = null;
    }
    updateCardPosition(x, y, type) {
        if (type == 'hover') {
            this.hoverCardPosition = {
                left: x,
                top: y,
            };
        }
        else if (type = 'comment') {
            this.commentPosition = {
                left: x,
                top: y,
            };
        }
        else {
            this.hideHoverCard();
            this.hideCommentCard();
        }
    }
};
