let ScheduledJobsModalComponent = class ScheduledJobsModalComponent {
    // elRef is used when parent components want to access this component's native element
    constructor(rsService, elRef) {
        this.rsService = rsService;
        this.elRef = elRef;
        this.scheduledJobsModalClasses = new Set(['scheduled-jobs-modal']);
        this.visible = false;
    }
    ngOnChanges(changes) {
        if (changes.hasOwnProperty('data') && changes.data.currentValue) {
            this.processData();
        }
        if (this.position === 'left') {
            this.scheduledJobsModalClasses.add('left-positioned-modal');
        }
        if (this.isGraphView) {
            this.scheduledJobsModalClasses.add('graph-view-modal');
        }
    }
    processData() {
        this.scheduledJobsTableData = this.data.map((scheduledJob) => {
            const jobData = {
                Id: scheduledJob.Id,
                Name: scheduledJob.jobName,
                frequency: this.rsService.getFrequencyText(scheduledJob.runType, scheduledJob.cronExpression, false),
                nextRunDate: scheduledJob.startDate,
                timezoneId: scheduledJob.timezoneId,
            };
            if (this.isGraphView && scheduledJob.configSettings) {
                const notifications = [];
                if (scheduledJob.configSettings.emailNotificationsEnabled)
                    notifications.push('Email');
                if (scheduledJob.configSettings.slackNotificationsEnabled)
                    notifications.push('Slack');
                if (scheduledJob.configSettings.microsoftTeamsNotificationsEnabled)
                    notifications.push('Microsoft Teams');
                if (scheduledJob.configSettings.chatterNotificationsEnabled)
                    notifications.push('Chatter');
                jobData.notifications = notifications.length > 0 ? notifications.join(', ') : 'No';
                jobData.allowDedupe = scheduledJob.configSettings.allowDedupe;
                jobData.respectSchedules = scheduledJob.configSettings.respectSchedules;
            }
            return jobData;
        });
        this.setupTableConfig();
    }
    setupTableConfig() {
        const graphSpecificColumns = this.isGraphView
            ? [{
                    label: 'Merge Duplicates',
                    field: 'allowDedupe',
                    width: '85px',
                    render: (allowDedupe, rowData) => {
                        return allowDedupe ? 'Yes' : 'No';
                    },
                },
                {
                    label: 'Send Notification',
                    field: 'notifications',
                    width: '105px',
                },
                {
                    label: 'Respect Schedules',
                    field: 'respectSchedules',
                    width: '85px',
                    render: (respectSchedules, rowData) => {
                        return respectSchedules ? 'Yes' : 'No';
                    },
                }]
            : [];
        // Note: padding to specs is increased by 10px (20px for last column) due to padding not being included in width
        this.scheduledJobsTableConfig = {
            paginate: this.scheduledJobsTableData.length > 10,
            rowHeight: '25px',
            customHeaderPadding: '0px 15px 0px 0px',
            customColumnPadding: '10px 15px 10px 0px',
            columns: [
                {
                    label: 'Job Name',
                    field: 'Name',
                    width: '200px',
                    escapeData: true,
                    customHeaderPadding: '0px 15px 0px 10px',
                    customColumnPadding: '10px 15px 10px 10px',
                    render: (colData, rowData) => {
                        return `<a class="ld-link truncate-with-ellipsis" href="#routing/routing_scheduler/schedule_routing_job/${rowData.Id}" target="_blank">${colData}</a>`;
                    },
                },
                {
                    label: 'Frequency',
                    field: 'frequency',
                    width: '90px',
                },
                ...graphSpecificColumns,
                {
                    label: 'Next Run Date',
                    field: 'nextRunDate',
                    width: '150px',
                    customHeaderPadding: '0px 10px 0px 15px',
                    customColumnPadding: '10px 10px 10px 15px',
                    render: (nextRunDate, rowData) => {
                        return nextRunDate ? this.rsService.formatScheduledDate(nextRunDate, false, rowData.timezoneId) : (rowData.frequency === 'One-Time' ? 'ASAP' : 'Scheduling...');
                    },
                }
            ],
        };
    }
    handleModalClick($event) {
        // Prevent other event clicks closing the modal when the parent or surrounding elements have click handlers too
        $event.stopPropagation();
    }
    toggleModal() {
        this.visible = !this.visible;
    }
    hideModal($event) {
        if ($event)
            $event.stopPropagation();
        this.visible = false;
    }
};
